let baseData={scripts:[{"id":"H-TH-001","title":"El error que me cost\u00f3 mi primer cliente","pillar":"founder","series":"","objective":"connection","format":"hablar-a-camara","duration":"30–45s","hook":"Perd\u00ed mi primer cliente por hacer exactamente lo que todos me dijeron que hiciera. (recomendado: grabarlo caminando o sentado directo a c\u00e1mara, expresi\u00f3n de vulnerabilidad genuina)","hookOptions":["El consejo que más escuché fue el que más daño me hizo.", "Hice todo bien. Y aun así, me fue mal. Esto es lo que aprendí.", "Nadie me dijo que el mejor momento para aprender sería cuando perdiera algo importante."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-TH-002","title":"Lo que nadie te dice del marketing en LinkedIn","pillar":"business","series":"","objective":"authority","format":"hablar-a-camara","duration":"30–45s","hook":"Llevas meses publicando en LinkedIn y los resultados son un desastre. El problema no es tu contenido. Es esto. (recomendado: empezar con una pausa larga antes de decir 'es esto', genera tensi\u00f3n)","hookOptions":["Lo que más me costó entender de LinkedIn no fue el algoritmo. Fue entender a la persona que me lee.", "Si publicas en LinkedIn sin entender estas [X] reglas no escritas, estás perdiendo el tiempo.", "Mi estrategia de LinkedIn pasó de cero a [X] contactos haciendo una sola cosa diferente."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-TH-003","title":"C\u00f3mo la IA cambi\u00f3 mi rutina de trabajo","pillar":"ai","series":"","objective":"discovery","format":"hablar-a-camara","duration":"30–45s","hook":"Antes tardaba [X] horas en esto. Ahora tardo [X] minutos. Y no, no es magia. Es IA bien aplicada. (recomendado: mostrar el contraste con gestos o pausas, hablar despacio)","hookOptions":["La IA no me reemplazó. Me hizo mejor en lo que hago. Así es cómo.", "Hay una forma de usar IA que muy poca gente conoce y que cambia todo.", "Si usas ChatGPT solo para escribir correos, estás desperdiciando la herramienta más poderosa de tu época."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-TH-004","title":"El modelo mental que uso para tomar decisiones en mi startup","pillar":"founder","series":"","objective":"authority","format":"hablar-a-camara","duration":"30–45s","hook":"Tomar decisiones en una startup no es dif\u00edcil cuando tienes el marco correcto. El problema es que nadie te lo ense\u00f1a. (recomendado: postura segura, voz pausada y directa, buen encuadre)","hookOptions":["Hay una pregunta que me hago antes de tomar cualquier decisión importante. Hoy te la comparto.", "Decidir mal en una startup no te mata en el momento. Te mata tres meses después. Por eso uso esto.", "Copié este modelo mental de los mejores fundadores. Me ahorró meses de confusión."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-TH-005","title":"El miedo que paraliza a todos los emprendedores","pillar":"personal","series":"","objective":"connection","format":"hablar-a-camara","duration":"30–45s","hook":"Hay un miedo que no me atrev\u00eda a decir en voz alta. Y resulta que lo tienen casi todos los fundadores que conozco. (recomendado: hablar en voz baja al inicio, como confidencia, crear cercan\u00eda)","hookOptions":["El miedo al fracaso no es lo que más paraliza. Hay algo peor. Y es silencioso.", "Nadie habla de esto en el mundo startup: el miedo de que quizás sí eres el problema.", "Hay una semana en la vida de todo emprendedor donde considera rendirse. Esta es la mía."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-TH-006","title":"Automatic\u00e9 esta parte de mi negocio y no lo creer\u00e1s","pillar":"automation","series":"","objective":"discovery","format":"hablar-a-camara","duration":"30–45s","hook":"Automatic\u00e9 el [X]% de mis seguimientos de ventas. Sin contratar a nadie. Sin pagar una fortuna. As\u00ed lo hice. (recomendado: ser espec\u00edfico con los n\u00fameros reales cuando tengas los datos)","hookOptions":["Hay tareas en tu negocio que podrías estar eliminando hoy mismo con automatización básica.", "Lo que más tiempo me robaba en mi empresa no era lo que yo creía. Y la automatización me lo demostró.", "Antes de contratar a alguien, pregúntate esto: ¿podría una herramienta hacer esto por mí?"],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-TH-007","title":"Por qu\u00e9 publico aunque nadie me vea","pillar":"personal","series":"","objective":"connection","format":"hablar-a-camara","duration":"30–45s","hook":"Durante meses publiqu\u00e9 contenido y nadie me vio. Aqu\u00ed est\u00e1 lo que eso me ense\u00f1\u00f3 sobre construir algo real. (recomendado: m\u00e1xima honestidad en el tono, sin artificios)","hookOptions":["El algoritmo no fue mi primer enemigo. La duda de si valía la pena fue peor.", "Hay algo que pasa cuando decides publicar aunque nadie esté mirando. Algo que no esperaba.", "No empecé a crecer hasta que dejé de importarme crecer. Y esto es lo que quiero decir con eso."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-TH-008","title":"La noticia de IA que m\u00e1s me preocup\u00f3 esta semana","pillar":"ai","series":"","objective":"discovery","format":"hablar-a-camara","duration":"30–45s","hook":"Hay una noticia de IA que sali\u00f3 esta semana y que casi nadie est\u00e1 hablando de ella. Y creo que deber\u00eda preocuparnos. (recomendado: actualizar con la noticia real de la semana que publiques)","hookOptions":["Esta semana en IA pasaron [X] cosas importantes. La más relevante para nosotros como emprendedores es esta.", "El avance de IA de esta semana cambia algo concreto en cómo deberías trabajar hoy.", "Mientras todos hablan de [modelo grande], lo que realmente importa pasó aquí."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-TH-009","title":"C\u00f3mo consegu\u00ed mi primer demo con un cliente real","pillar":"business","series":"","objective":"connection","format":"hablar-a-camara","duration":"30–45s","hook":"Mi primer demo de producto lo consegu\u00ed de una manera que jam\u00e1s habr\u00eda planeado. Y ahora lo uso como m\u00e9todo. (recomendado: contar la historia como si fuera la primera vez, con energ\u00eda genuina)","hookOptions":["El outreach frío no funcionó. Lo que sí funcionó fue esto.", "Cometí [X] errores antes de conseguir mi primera reunión de demo. Este es el proceso limpio.", "Nadie quería verme hasta que cambié una sola cosa en cómo presentaba el problema."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-TH-010","title":"El sistema de productividad que cambi\u00f3 mi semana","pillar":"personal","series":"","objective":"discovery","format":"hablar-a-camara","duration":"30–45s","hook":"Prob\u00e9 [X] sistemas de productividad en [X] meses. Este es el \u00fanico que sobrevivi\u00f3. (recomendado: ser espec\u00edfico con los sistemas que realmente probaste antes)","hookOptions":["No soy productivo por naturaleza. Soy productivo porque tengo un sistema que no depende de motivación.", "El mayor error que cometí en mi productividad no fue la distracción. Fue esto otro.", "Hay una pregunta que me hago cada domingo que define qué tan bien va a ir mi semana."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-TH-011","title":"Lo que descubr\u00ed al analizar mis m\u00e9tricas de contenido","pillar":"business","series":"","objective":"authority","format":"hablar-a-camara","duration":"30–45s","hook":"Revis\u00e9 mis \u00faltimos [X] reels y encontr\u00e9 un patr\u00f3n que no esperaba ver. Aqu\u00ed est\u00e1 lo que cambi\u00e9. (recomendado: mostrar apertura real a los datos, no performance)","hookOptions":["El contenido que creía que iba a volar fue el que peor funcionó. Y viceversa.", "Hay un indicador en tus métricas que importa más que los views. ¿Lo estás midiendo?", "Después de [X] semanas publicando, aprendí más de mis fracasos que de mis éxitos."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-TH-012","title":"Lo que aprend\u00ed construyendo un SaaS desde cero","pillar":"founder","series":"","objective":"authority","format":"hablar-a-camara","duration":"30–45s","hook":"Nadie me dijo que construir un SaaS no era solo un problema t\u00e9cnico. Era principalmente un problema de ventas. (recomendado: tono reflexivo, no condescendiente, compartir la lecci\u00f3n como si te costara admitirla)","hookOptions":["El error más caro que cometí en mi SaaS fue construir antes de vender.", "Hay [X] cosas que haría diferente si empezara mi startup hoy.", "Lo más difícil del SaaS no fue el código. Fue este otro problema que nadie menciona."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-TH-013","title":"Por qu\u00e9 la automatizaci\u00f3n no es para todos","pillar":"automation","series":"","objective":"authority","format":"hablar-a-camara","duration":"30–45s","hook":"Hay personas que no deber\u00edan automatizar todav\u00eda. Y si eres emprendedor nuevo, probablemente eres una de ellas. (recomendado: tono provocador pero honesto, espera reacci\u00f3n antes de explicar)","hookOptions":["Automatizar sin claridad es como optimizar un barco que va en la dirección equivocada.", "Antes de automatizar, hazte esta pregunta. Si no puedes responderla, espera.", "El error más caro en automatización no es hacerlo mal. Es hacerlo antes de tiempo."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-TH-014","title":"C\u00f3mo uso la IA para crear contenido sin perder mi voz","pillar":"ai","series":"","objective":"discovery","format":"hablar-a-camara","duration":"30–45s","hook":"Uso IA para crear contenido todos los d\u00edas. Y no suena a robot. Aqu\u00ed est\u00e1 mi proceso exacto. (recomendado: mostrar el resultado real antes de explicar el proceso)","hookOptions":["El problema de usar IA para contenido no es la calidad. Es que todos parecen el mismo.", "Hay una forma de usar IA que potencia tu voz en vez de apagarla. Esta es la mía.", "Mi contenido lo genera la IA. Mis ideas siguen siendo mías. Así se hace eso."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-TH-015","title":"El h\u00e1bito que m\u00e1s ha impactado mi crecimiento personal","pillar":"personal","series":"","objective":"connection","format":"hablar-a-camara","duration":"30–45s","hook":"Si tuviera que elegir un solo h\u00e1bito que cambi\u00f3 mi vida como emprendedor, ser\u00eda este. Y no es lo que imaginas. (recomendado: pausa larga despu\u00e9s de 'este', romper la expectativa del h\u00e1bito obvio)","hookOptions":["No es la meditación. No es el ejercicio. Es algo que casi nadie habla y que cambió todo.", "Llevo [X] años haciendo esto cada mañana. Es lo más aburrido que hago. Y lo más valioso.", "El hábito más importante de mi semana no es de productividad. Es de claridad."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-TH-016","title":"La conversaci\u00f3n que me hizo replantear todo","pillar":"founder","series":"","objective":"connection","format":"hablar-a-camara","duration":"30–45s","hook":"Tuve una conversaci\u00f3n con un fundador m\u00e1s experimentado que me hizo cuestionar todo lo que estaba haciendo. Esto fue lo que me dijo. (recomendado: contar como momento de inflexi\u00f3n real, no como lecci\u00f3n preparada)","hookOptions":["Hay una pregunta que me hicieron que no supe responder. Y eso me dijo todo.", "El mentor que no busqué me encontró en el momento exacto que lo necesitaba.", "No esperaba que esa conversación de [X] minutos cambiara mi hoja de ruta completa."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-TH-017","title":"Por qu\u00e9 la mayor\u00eda de los fundadores no consiguen clientes","pillar":"business","series":"","objective":"authority","format":"hablar-a-camara","duration":"30–45s","hook":"El problema no es el producto. No es el precio. No es el mercado. Es algo que nadie quiere escuchar. (recomendado: construir tensi\u00f3n enumerando las excusas antes de dar la respuesta real)","hookOptions":["La mayoría de los emprendedores que no consiguen clientes tienen exactamente el mismo problema.", "Vender no es un talento. Es un proceso. Y si no tienes proceso, no tienes ventas.", "Hay una sola razón por la que los fundadores técnicos no consiguen clientes. Esta es."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-TH-018","title":"Lo que m\u00e1s me sorprendi\u00f3 de la IA generativa este a\u00f1o","pillar":"ai","series":"","objective":"discovery","format":"hablar-a-camara","duration":"30–45s","hook":"Llevo [X] meses usando IA todos los d\u00edas en mi trabajo. Esto es lo que m\u00e1s me sorprendi\u00f3. No es lo que crees. (recomendado: ser genuinamente sorpresivo, no lo t\u00edpico que todo el mundo dice)","hookOptions":["La IA no es tan buena como dicen en esto. Pero es mucho mejor de lo que imaginaba en lo otro.", "Después de [X] meses usando IA en mi startup, encontré sus límites reales. Aquí están.", "Hay una capacidad de la IA que casi nadie usa y que cambia completamente el juego."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-TH-019","title":"El sistema de automatizaci\u00f3n que uso para mis ventas","pillar":"automation","series":"","objective":"discovery","format":"hablar-a-camara","duration":"30–45s","hook":"Mis ventas corren solas mientras yo duermo. No es un mito. Es un sistema que constru\u00ed en [X] d\u00edas. (recomendado: demostrar confianza en el sistema, dar n\u00famero real de d\u00edas cuando lo tengas)","hookOptions":["El mejor vendedor de mi empresa no es humano. Es un flujo de automatización que no para nunca.", "Dejé de perseguir clientes cuando entendí que el seguimiento podía ser automático.", "Hay [X] herramientas que uso para automatizar ventas sin perder el toque personal."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-TH-020","title":"El momento en que quise dejarlo todo","pillar":"personal","series":"","objective":"connection","format":"hablar-a-camara","duration":"30–45s","hook":"Hubo un momento en que quise cerrar todo, borrar mis redes y desaparecer. Hoy me alegra no haberlo hecho. (recomendado: m\u00e1xima vulnerabilidad, sin producci\u00f3n excesiva, que se vea real)","hookOptions":["El peor mes de mi vida como emprendedor fue también el más importante. Te cuento por qué.", "No te cuento los éxitos para inspirarte. Te cuento esto porque es lo que necesito que sepas.", "Hay una semana que marcó un antes y un después en mi historia de fundador. Esta es."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-TH-021","title":"Qu\u00e9 hacer cuando el producto no vende","pillar":"business","series":"","objective":"authority","format":"hablar-a-camara","duration":"30–45s","hook":"Tu producto no vende. No es el producto. No es el precio. Esto es lo que tienes que cambiar primero. (recomendado: directo, sin rodeos, como si se lo dijeras a un amigo honestamente)","hookOptions":["Hay [X] síntomas que te dicen que el problema no es tu producto sino tu mensaje.", "Antes de cambiar el producto, cambia esto. Después me cuentas.", "Si nadie compra, el problema casi siempre está aquí, no donde crees."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-TH-022","title":"La herramienta de IA que m\u00e1s recomiendo a fundadores","pillar":"ai","series":"","objective":"discovery","format":"hablar-a-camara","duration":"30–45s","hook":"Si solo pudiera recomendarte una herramienta de IA como fundador, ser\u00eda esta. Y probablemente no la est\u00e1s usando. (recomendado: actualiza la herramienta seg\u00fan el contexto del momento que publiques)","hookOptions":["No te voy a recomendar ChatGPT. Ya lo conoces. Esta herramienta hace algo diferente.", "Hay [X] herramientas de IA que uso en mi startup. Esta es la que más sorprende a la gente.", "La herramienta de IA más subestimada para emprendedores es esta. Aquí por qué."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-TH-023","title":"El error de pricing que casi mata mi startup","pillar":"business","series":"","objective":"connection","format":"hablar-a-camara","duration":"30–45s","hook":"Puse un precio a mi producto que hizo exactamente lo contrario de lo que esperaba. Y aqu\u00ed est\u00e1 por qu\u00e9 fue un error que no vi venir. (recomendado: ser espec\u00edfico con los n\u00fameros reales que tengas)","hookOptions":["El precio más bajo no siempre es el que más vende. Aprendí esto de la peor manera.", "Cambié el precio de mi producto [X] veces antes de encontrar el punto correcto.", "Hay una psicología detrás del pricing que nadie te enseña y que lo cambia todo."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-TH-024","title":"Por qu\u00e9 empec\u00e9 a construir en p\u00fablico","pillar":"founder","series":"","objective":"connection","format":"hablar-a-camara","duration":"30–45s","hook":"Empec\u00e9 a publicar el proceso de mi startup mientras la constru\u00eda. Y cambi\u00f3 todo, para bien y para mal. (recomendado: honestidad sobre el costo real del build in public, no solo los beneficios)","hookOptions":["Construir en público tiene costos que nadie te dice. Y también beneficios que no esperaba.", "No sabía si compartir que estaba construyendo algo antes de que funcionara. Lo hice igual. Esto pasó.", "El día que decidí compartir mi proceso fue el día que dejé de sentirme solo en esto."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-TH-025","title":"C\u00f3mo el desarrollo personal cambi\u00f3 mi negocio","pillar":"personal","series":"","objective":"connection","format":"hablar-a-camara","duration":"30–45s","hook":"Mi negocio creci\u00f3 cuando yo crec\u00ed. No es una frase motivacional. Es lo que vi pasar con datos reales. (recomendado: ser espec\u00edfico sobre qu\u00e9 cambi\u00f3 en ti y qu\u00e9 cambi\u00f3 en el negocio como consecuencia)","hookOptions":["El trabajo más importante que hice en mi startup fue en mí mismo. Aquí está la conexión.", "La mentalidad no es un concepto vago. Es la diferencia entre escalar o no escalar.", "Hay un libro/hábito/práctica que cambió mi forma de tomar decisiones de negocio. Este es."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-TH-026","title":"C\u00f3mo automatic\u00e9 mi onboarding de clientes","pillar":"automation","series":"","objective":"discovery","format":"hablar-a-camara","duration":"30–45s","hook":"Antes cada cliente nuevo me costaba [X] horas. Ahora el onboarding es autom\u00e1tico y mejor. As\u00ed lo constru\u00ed. (recomendado: dar el n\u00famero real de horas que tardabas, hace el contraste m\u00e1s poderoso)","hookOptions":["El onboarding manual me estaba consumiendo. La solución fue más simple de lo que pensé.", "Mis clientes nuevos ahora tienen una experiencia mejor y yo no hago casi nada. Aquí está el sistema.", "Hay [X] pasos que automaticé en mi onboarding que cambiaron cómo perciben mi empresa desde el día uno."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-TH-027","title":"La noticia de IA que m\u00e1s me entusiasm\u00f3 este mes","pillar":"ai","series":"","objective":"discovery","format":"hablar-a-camara","duration":"30–45s","hook":"Este mes en IA pas\u00f3 algo que cambia completamente el tablero para los emprendedores peque\u00f1os. Y casi nadie lo cubri\u00f3 bien. (recomendado: actualizar con noticia real al momento de publicar, especificar la fuente)","hookOptions":["Los grandes laboratorios de IA lanzaron algo esta semana. Esto es lo que significa para nosotros.", "Hay un avance de IA de este mes que afecta directamente lo que estás construyendo.", "Si no te enteraste de esto en IA esta semana, aquí está el resumen que importa."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-TH-028","title":"Lo que cambiar\u00eda si empezara mi startup de nuevo","pillar":"founder","series":"","objective":"authority","format":"hablar-a-camara","duration":"30–45s","hook":"Si pudiera volver al d\u00eda uno de mi startup con lo que s\u00e9 hoy, har\u00eda [X] cosas completamente diferente. (recomendado: hacer lista concreta, no gen\u00e9rica, basada en tu experiencia real)","hookOptions":["El fundador que soy hoy le daría [X] consejos al fundador que era hace [X] meses.", "Perdí [X] meses haciendo esto que no servía de nada. Aquí por qué lo seguí haciendo.", "No es lo que no sabía lo que me costó más. Es lo que creía saber y estaba equivocado."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-TH-029","title":"La diferencia entre los fundadores que escalan y los que no","pillar":"business","series":"","objective":"authority","format":"hablar-a-camara","duration":"30–45s","hook":"He observado fundadores que escalan y fundadores que no. La diferencia no es el producto ni el dinero. Es esto. (recomendado: pausa dram\u00e1tica antes de revelar la diferencia)","hookOptions":["Los fundadores que llegan a [X] en ingresos comparten un rasgo que no es talento.", "Hay una cosa que separa a los startups que sobreviven de los que no. ¿La conoces?", "El factor diferenciador en startups no es lo que te enseñan en los libros. Es este."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-TH-030","title":"El proceso para crear contenido sin bloquearse","pillar":"personal","series":"","objective":"discovery","format":"hablar-a-camara","duration":"30–45s","hook":"El bloqueo creativo no existe. Existe la falta de sistema. Aqu\u00ed est\u00e1 el que uso para nunca quedarme sin qu\u00e9 decir. (recomendado: tono pr\u00e1ctico y directo, sin romanticismo del proceso creativo)","hookOptions":["Nunca me quedo sin ideas para contenido. No porque sea creativo sino porque tengo este proceso.", "El problema no es la inspiración. Es que no tienes un sistema de captura. Aquí está el mío.", "Hay [X] fuentes de ideas que siempre me dan contenido relevante. Estas son las que uso."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-PD-001","title":"Yo vs. el promedio: datos reales sobre eficiencia","pillar":"automation","series":"","objective":"discovery","format":"pantalla-dividida","duration":"30–45s","hook":"Pantalla izquierda: yo haciendo esto manualmente. Pantalla derecha: mi automatizaci\u00f3n haci\u00e9ndolo. El resultado te va a sorprender. (recomendado: screencast real de la automatizaci\u00f3n en la pantalla derecha, pantalla izquierda el proceso manual o tu cara)","hookOptions":["Esta es la diferencia entre hacer algo a mano y dejar que un sistema lo haga por ti.", "Izquierda: cómo lo hacía antes. Derecha: cómo lo hago ahora. Tiempo ahorrado: [X].", "Este es el antes y el después de mi flujo de trabajo después de automatizar."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-PD-002","title":"LinkedIn: mito vs. realidad","pillar":"business","series":"","objective":"authority","format":"pantalla-dividida","duration":"30–45s","hook":"Lo que dicen que funciona en LinkedIn vs. lo que realmente funciona. Este es el contraste que nadie hace. (recomendado: pantalla izquierda con texto del consejo com\u00fan, pantalla derecha con tu experiencia real en datos)","hookOptions":["Consejo popular de LinkedIn: [X]. Lo que yo hice en cambio: [Y]. Resultado: [Z].", "Hay [X] mitos de LinkedIn que siguen circulando. Esta es la realidad detrás de cada uno.", "Antes vs. después de cambiar mi estrategia de LinkedIn: estas son las métricas reales."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-PD-003","title":"IA esperada vs. IA real","pillar":"ai","series":"","objective":"connection","format":"pantalla-dividida","duration":"30–45s","hook":"Lo que la gente espera de la IA vs. lo que realmente hace cuando la usas en tu trabajo. Esta es la brecha que nadie habla. (recomendado: pantalla izquierda con expectativas infladas de medios, pantalla derecha con uso pr\u00e1ctico real)","hookOptions":["Media: la IA va a reemplazar tu trabajo. Realidad: la IA te pide que seas más humano.", "Lo que prometen los demos de IA vs. lo que pasa cuando lo implementas tú mismo.", "Expectativa de la IA: [X]. Realidad de usarla todos los días: [Y]. Esta es la diferencia."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-PD-004","title":"Fundador de \u00e9xito vs. fundador promedio","pillar":"founder","series":"","objective":"authority","format":"pantalla-dividida","duration":"30–45s","hook":"\u00bfQu\u00e9 hace diferente un fundador que escala de uno que se estanca? Te lo muestro con datos reales en pantalla. (recomendado: comparar h\u00e1bitos, decisiones o m\u00e9tricas concretas, no generalidades motivacionales)","hookOptions":["Fundador estancado en [X]: hace esto. Fundador que escala: hace esto otro. La diferencia es clara.", "Comparé [X] fundadores exitosos con [X] que fracasaron. Este es el patrón que encontré.", "No es el talento lo que separa. Es el sistema. Te lo muestro con ejemplos concretos."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-PD-005","title":"Mi d\u00eda sin automatizaci\u00f3n vs. con automatizaci\u00f3n","pillar":"automation","series":"","objective":"discovery","format":"pantalla-dividida","duration":"30–45s","hook":"Mi agenda un lunes sin automatizaci\u00f3n. Mi agenda un lunes con automatizaci\u00f3n. La diferencia en horas libres te va a impactar. (recomendado: mostrar screenshot real o recreaci\u00f3n de ambas agendas, datos concretos)","hookOptions":["Antes: [X] horas en tareas administrativas. Después: [X] minutos. Mismo resultado.", "Este es cómo se ve mi semana antes y después de implementar automatizaciones.", "La automatización no me dio más tiempo. Me devolvió el tiempo que ya tenía."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-PD-006","title":"El consejo de los libros vs. la realidad del negocio","pillar":"business","series":"","objective":"connection","format":"pantalla-dividida","duration":"30–45s","hook":"Lo que dice el libro de negocios m\u00e1s famoso vs. lo que yo experiment\u00e9 al aplicarlo. No siempre coinciden. (recomendado: cita textual del libro en una pantalla, tu experiencia real en la otra)","hookOptions":["El libro dice: [X]. La realidad de aplicarlo fue: [Y]. ¿Cuál fue el error?", "Hay [X] consejos de negocios que suenan bien en teoría pero fallan en la práctica. Este es el primero.", "No todo lo que lees en libros de startup aplica a tu realidad. Estos son los que sí y los que no."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-PD-007","title":"Antes y despu\u00e9s de encontrar mi nicho","pillar":"personal","series":"","objective":"connection","format":"pantalla-dividida","duration":"30–45s","hook":"Pantalla izquierda: yo intentando hablarle a todos. Pantalla derecha: yo habl\u00e1ndole a alguien espec\u00edfico. El cambio fue brutal. (recomendado: mostrar ejemplos concretos de contenido o mensajes de ventas del antes vs. despu\u00e9s)","hookOptions":["Antes de encontrar mi nicho vs. después. Este es el impacto en números.", "Intenté hablarle a todo el mundo. Nadie me escuchó. Cuando elegí a una persona, todo cambió.", "El momento en que dejé de intentar ser para todos fue el momento en que empecé a crecer."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-PD-008","title":"Lo que dice la IA sobre tu industria vs. lo que es real","pillar":"ai","series":"","objective":"authority","format":"pantalla-dividida","duration":"30–45s","hook":"Le pregunt\u00e9 a [herramienta de IA] sobre mi industria. Esto es lo que me dijo. Y esto es lo que la realidad dice. El contraste es importante. (recomendado: screenshot real de la respuesta de IA vs. dato verificable de fuente confiable)","hookOptions":["IA sobre [tema de tu industria]: [respuesta]. Realidad según [fuente]: [dato real]. ¿Cuál creer?", "Los datos que genera la IA sobre negocios no siempre son precisos. Aquí un ejemplo concreto.", "Confiar ciegamente en la IA para decisiones de negocio puede costarte caro. Este es un caso real."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-PD-009","title":"Mi versi\u00f3n de redes vs. la versi\u00f3n real de un experto","pillar":"business","series":"","objective":"connection","format":"pantalla-dividida","duration":"30–45s","hook":"Mi perfil de LinkedIn cuando empec\u00e9 vs. c\u00f3mo se ve ahora. Lo que cambi\u00e9 y por qu\u00e9 marca una diferencia enorme. (recomendado: screenshot comparativo real o recreaci\u00f3n, con flechas se\u00f1alando los cambios clave)","hookOptions":["Esto es lo que tenía en mi perfil antes. Esto es lo que tengo ahora. El impacto fue inmediato.", "Hay [X] cambios que hice en mi presencia online que duplicaron mi alcance.", "Versión 1.0 de mi perfil vs. versión actual. Aquí están los errores que corregí."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-PD-010","title":"Emprendedor exitoso vs. emprendedor quemado","pillar":"personal","series":"","objective":"connection","format":"pantalla-dividida","duration":"30–45s","hook":"Hay una diferencia visible entre el emprendedor que est\u00e1 creciendo y el que est\u00e1 quem\u00e1ndose. \u00bfEn cu\u00e1l te reconoces? (recomendado: dos retratos o situaciones contrastantes, uno de energ\u00eda y uno de agotamiento)","hookOptions":["Antes: todo urgente, todo importante, todo a la vez. Después: esto cambió cuando aprendí esto.", "No es el trabajo duro lo que te quema. Es el trabajo sin dirección. Esta es la diferencia.", "El burnout del emprendedor no llega de repente. Llega con estas señales que ignoré por meses."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-PD-011","title":"Mis herramientas de IA favoritas vs. las sobrevaloradas","pillar":"ai","series":"","objective":"authority","format":"pantalla-dividida","duration":"30–45s","hook":"Herramientas de IA que todos recomiendan vs. las que yo realmente uso. No siempre es la misma lista. (recomendado: lista visual de herramientas populares vs. tu lista real con razones concretas)","hookOptions":["Pantalla izquierda: top 5 herramientas de IA según internet. Pantalla derecha: las que uso yo y por qué.", "Hay herramientas de IA que son hype puro. Estas son las que sí dan resultados reales.", "De [X] herramientas de IA que probé, estas [X] sobrevivieron a mi proceso de selección."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-PD-012","title":"Proceso manual vs. proceso automatizado en ventas","pillar":"automation","series":"","objective":"discovery","format":"pantalla-dividida","duration":"30–45s","hook":"Seguimiento de ventas manual: [X] pasos, [Y] horas. Flujo automatizado: mismo resultado, [Z] minutos. El contraste en pantalla. (recomendado: mostrar pantallas reales del CRM o herramienta, no ilustraciones)","hookOptions":["Así era mi proceso de ventas antes. Así es ahora. La eficiencia cambió completamente.", "Izquierda: lo que le costaba tiempo a mi equipo. Derecha: lo que hace el sistema solo.", "Automatizar ventas no es perder el toque humano. Es recuperar tiempo para el toque humano."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-PD-013","title":"Lo que el mundo dice del SaaS vs. la realidad de construirlo","pillar":"founder","series":"","objective":"connection","format":"pantalla-dividida","duration":"30–45s","hook":"Twitter/X dice que construir un SaaS es f\u00e1cil. Mi experiencia real dice otra cosa. Este es el contraste honesto. (recomendado: citas reales de Twitter en una pantalla vs. momentos reales de tu proceso en la otra)","hookOptions":["El glamour de fundar un SaaS en redes vs. la realidad de mis últimas [X] semanas.", "Lo que los success stories no te muestran del proceso de construir un producto.", "Fundador en LinkedIn: todo va perfecto. Fundador en la vida real: esto es lo que no publican."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-PD-014","title":"Qu\u00e9 hace diferente un contenido que viraliza vs. uno que no","pillar":"business","series":"","objective":"authority","format":"pantalla-dividida","duration":"30–45s","hook":"Este reel tuvo [X] views. Este otro tuvo [X]. La diferencia no fue el tema. Fue esto que te voy a mostrar. (recomendado: usar tus propios reels reales o pantallas de m\u00e9tricas para hacerlo cre\u00edble)","hookOptions":["Mismo formato, mismo tema, misma calidad. Uno voló, el otro no. ¿Qué fue diferente?", "Analicé [X] reels de alto rendimiento vs. [X] de bajo rendimiento. Este es el patrón.", "El gancho lo es todo. Aquí está la diferencia visual entre un gancho que para el scroll y uno que no."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-PD-015","title":"Lo que me dec\u00eda antes vs. lo que me digo ahora","pillar":"personal","series":"","objective":"connection","format":"pantalla-dividida","duration":"30–45s","hook":"El di\u00e1logo interno del emprendedor en el a\u00f1o uno vs. el a\u00f1o [X]. Esta es la evoluci\u00f3n que nadie muestra pero todos viven. (recomendado: texto o voz en off de pensamientos reales del pasado vs. presente)","hookOptions":["Antes me decía: 'esto no va a funcionar'. Ahora me digo: esto otra cosa. El cambio fue este.", "Lo que me paralizaba antes vs. lo que me impulsa ahora. Esta es la mentalidad real del crecimiento.", "Mis miedos de emprendedor en el mes uno vs. mis miedos ahora. Cambian. Y eso importa."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-PD-016","title":"Decisi\u00f3n r\u00e1pida vs. decisi\u00f3n analizada: \u00bfcu\u00e1l gan\u00f3?","pillar":"founder","series":"","objective":"authority","format":"pantalla-dividida","duration":"30–45s","hook":"Tom\u00e9 [X] decisiones r\u00e1pidas este mes y [X] analizadas. \u00bfCu\u00e1les funcionaron mejor? El resultado me sorprendi\u00f3. (recomendado: ser espec\u00edfico con las decisiones reales, no abstracciones)","hookOptions":["Análisis vs. instinto en decisiones de startup. Los números muestran algo interesante.", "Me forzé a tomar una decisión importante en 10 minutos. Esto es lo que pasó.", "Hay decisiones que necesitan datos y decisiones que necesitan velocidad. Aprende a distinguirlas."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-PD-017","title":"IA cara vs. IA gratuita: \u00bfvale la diferencia?","pillar":"ai","series":"","objective":"discovery","format":"pantalla-dividida","duration":"30–45s","hook":"Herramienta de IA de [X] d\u00f3lares al mes vs. herramienta gratuita. \u00bfLa diferencia justifica el precio? Hice el test. (recomendado: comparaci\u00f3n real con capturas de pantalla de ambas herramientas haciendo la misma tarea)","hookOptions":["Probé la versión de pago vs. la gratuita durante [X] semanas. Este es el veredicto honesto.", "¿Vale la pena pagar [X] al mes por esta herramienta de IA? Mi respuesta después de usarla en producción.", "No siempre la herramienta más cara es la mejor. Esta comparación lo demuestra."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-PD-018","title":"Mi rutina de trabajo antes vs. despu\u00e9s de tener un sistema","pillar":"personal","series":"","objective":"discovery","format":"pantalla-dividida","duration":"30–45s","hook":"As\u00ed era mi d\u00eda laboral ca\u00f3tico. As\u00ed es ahora con un sistema. La diferencia en calidad de vida es enorme. (recomendado: mostrar agenda real o calendario, antes vs. despu\u00e9s, con diferencia visual clara)","hookOptions":["Antes: reactivo a todo. Ahora: proactivo en lo que importa. Esto es lo que cambió.", "Mi rutina antes de tener un sistema vs. después. Las horas son las mismas. El resultado no.", "El sistema no te da más tiempo. Te devuelve el control sobre el tiempo que ya tienes."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-PD-019","title":"Mi startup en el mes 1 vs. el mes [X]","pillar":"founder","series":"","objective":"connection","format":"pantalla-dividida","duration":"30–45s","hook":"Mi startup en el mes uno: esto. Mi startup en el mes [X]: esto otro. El camino entre ambos no fue en l\u00ednea recta. (recomendado: pantallas comparativas reales del producto o dashboard de m\u00e9tricas)","hookOptions":["Mes 1: cero usuarios, cero ingresos, máxima energía. Mes [X]: estas son las métricas reales.", "El producto de mes uno vs. el producto de hoy. Lo que cambié y por qué.", "Nadie te muestra la versión fea del mes uno de un SaaS. Esta es la mía."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-PD-020","title":"Lo que hace un emprendedor productivo vs. uno ocupado","pillar":"business","series":"","objective":"authority","format":"pantalla-dividida","duration":"30–45s","hook":"Ocupado vs. productivo. Se parecen pero son completamente diferentes. Este contraste visual lo explica mejor que cualquier definici\u00f3n. (recomendado: lista visual contrastante con ejemplos concretos de tareas, no conceptos abstractos)","hookOptions":["El emprendedor ocupado hace [X]. El emprendedor productivo hace [Y]. ¿En cuál estás tú?", "Hay una diferencia entre trabajar mucho y trabajar en lo que importa. Esta es la prueba visual.", "Revisé mi semana pasada y encontré [X] horas perdidas en esto. Así las recuperé."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-PD-021","title":"Outreach en fr\u00edo manual vs. automatizado","pillar":"automation","series":"","objective":"discovery","format":"pantalla-dividida","duration":"30–45s","hook":"Enviar mensajes de outreach uno a uno vs. flujo automatizado personalizado. El resultado de tasa de respuesta te va a impactar. (recomendado: mostrar pantallas reales del proceso, tasas de respuesta reales)","hookOptions":["Manual: [X]% de respuesta. Automatizado con personalización: [Y]%. La diferencia fue esto.", "No sacrifiqué personalización cuando automaticé mi outreach. Aquí está cómo lo hice.", "El outreach en frío no muere cuando lo automatizas. Muere cuando lo haces sin personalización."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-PD-022","title":"C\u00f3mo genera contenido alguien sin IA vs. con IA","pillar":"ai","series":"","objective":"discovery","format":"pantalla-dividida","duration":"30–45s","hook":"Proceso de creaci\u00f3n de contenido sin IA: [X] horas. Con IA bien integrada: [Y] minutos. Esta es la diferencia visual. (recomendado: screencast real de ambos procesos o descripci\u00f3n muy concreta de pasos)","hookOptions":["Sin IA: abrir documento, pensar, escribir, editar, reformatear. Con IA: esto otro.", "No es que la IA escriba por mí. Es que elimina la parte más costosa de mi proceso.", "Así crea contenido alguien que no usa IA. Así lo crea alguien que sí. ¿Ves la diferencia?"],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-PD-023","title":"Precio de un servicio freelance vs. precio de un SaaS","pillar":"business","series":"","objective":"authority","format":"pantalla-dividida","duration":"30–45s","hook":"Ganar [X] como freelance vs. ganar [X] con un SaaS. Las horas dedicadas son completamente distintas. Este es el contraste real. (recomendado: n\u00fameros reales o aproximados, con contexto honesto del esfuerzo de cada modelo)","hookOptions":["Ingreso de servicio activo vs. ingreso recurrente de SaaS. La escala es diferente en todo.", "Por qué cambié de vender tiempo a vender producto. El contraste en números lo explica todo.", "Servicio: cobra cuando trabajas. SaaS: cobra cuando duermes. El proceso para llegar ahí es este."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-PD-024","title":"Mi bienestar antes vs. despu\u00e9s de establecer l\u00edmites","pillar":"personal","series":"","objective":"connection","format":"pantalla-dividida","duration":"30–45s","hook":"Emprendedor sin l\u00edmites vs. emprendedor con l\u00edmites claros. Lo que cambia no es solo el bienestar. Cambian los resultados. (recomendado: honestidad sobre el impacto real de no tener l\u00edmites, con ejemplos concretos)","hookOptions":["Antes contestaba mensajes a medianoche. Después de establecer límites, esto pasó.", "El límite más difícil que puse en mi negocio fue este. Y fue el más valioso.", "No es egoísta poner límites como emprendedor. Es necesario. Aquí está por qué en datos."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-PD-025","title":"C\u00f3mo responde la IA vs. c\u00f3mo respondo yo al mismo prompt","pillar":"ai","series":"","objective":"discovery","format":"pantalla-dividida","duration":"30–45s","hook":"Le di el mismo prompt a la IA y lo respond\u00ed yo tambi\u00e9n. La comparaci\u00f3n revela algo sobre c\u00f3mo usar estas herramientas inteligentemente. (recomendado: pantalla real de la respuesta de IA vs. tu respuesta manual, lado a lado)","hookOptions":["IA vs. yo: respondiendo la misma pregunta de negocio. El resultado fue sorprendente.", "Así responde ChatGPT. Así respondo yo. La diferencia muestra cuándo usar cada uno.", "No siempre la IA lo hace mejor. Y no siempre yo lo hago mejor. Esta comparación lo demuestra."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-PD-026","title":"Startup bootstrapped vs. startup con inversi\u00f3n","pillar":"founder","series":"","objective":"authority","format":"pantalla-dividida","duration":"30–45s","hook":"Bootstrapped vs. financiado externamente. No es mejor ni peor. Es diferente en todo. Este es el contraste real. (recomendado: comparar velocidad, presi\u00f3n, libertad y riesgo de forma concreta)","hookOptions":["Con inversión tienes más velocidad. Sin ella tienes más control. ¿Qué elegirías tú?", "Mi decisión de no buscar inversión fue intencional. Aquí está el razonamiento real.", "Bootstrapped: esto. Con VC: esto otro. Para mi contexto, este modelo tiene más sentido."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-PD-027","title":"Stack tecnol\u00f3gico con IA vs. sin IA","pillar":"automation","series":"","objective":"discovery","format":"pantalla-dividida","duration":"30–45s","hook":"Mi stack de herramientas antes de integrar IA vs. despu\u00e9s. Lo que elimine y lo que agregu\u00e9 cambi\u00f3 c\u00f3mo opera todo. (recomendado: lista visual real de herramientas en cada columna, con costos si es posible)","hookOptions":["Antes usaba [X] herramientas. Después de integrar IA, uso estas. El costo cambió así.", "Añadir IA a mi stack no fue complicado. Esto es lo que cambió y lo que no.", "Herramientas que uso sin IA vs. herramientas con IA integrada. El impacto en productividad."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-PD-028","title":"Noticias de IA de esta semana: lo que importa vs. lo que es ruido","pillar":"ai","series":"","objective":"authority","format":"pantalla-dividida","duration":"30–45s","hook":"Noticias de IA de esta semana: las que son hype vs. las que realmente cambian algo. Filtro el ruido en pantalla. (recomendado: listar titulares reales de la semana, clasificarlos visualmente, actualizar cada semana que uses este hook)","hookOptions":["Izquierda: lo que los medios dijeron de IA esta semana. Derecha: lo que realmente importa.", "De [X] noticias de IA de esta semana, solo estas [X] cambian algo en cómo trabajas.", "El filtro de noticias de IA que uso para quedarme solo con lo que me importa como fundador."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-PD-029","title":"Crecimiento org\u00e1nico vs. paid: \u00bfcu\u00e1l funciona para startups peque\u00f1as?","pillar":"business","series":"","objective":"authority","format":"pantalla-dividida","duration":"30–45s","hook":"Invert\u00ed [X] en ads y [X] horas en contenido org\u00e1nico. Los resultados no fueron los que esperaba. Este es el contraste real. (recomendado: datos reales de tus propias campa\u00f1as cuando los tengas disponibles)","hookOptions":["Contenido orgánico vs. publicidad pagada en LinkedIn para conseguir demos. Los números reales.", "Hay un momento para escalar con ads. Pero primero tienes que pasar por esto.", "El CAC (costo de adquisición) del canal orgánico vs. el paid. La diferencia me sorprendió."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-PD-030","title":"Mentalidad fija vs. mentalidad de crecimiento en acci\u00f3n real","pillar":"personal","series":"","objective":"connection","format":"pantalla-dividida","duration":"30–45s","hook":"La diferencia entre mentalidad fija y de crecimiento no es conceptual. Es esto que se ve en el d\u00eda a d\u00eda. Aqu\u00ed el contraste. (recomendado: ejemplos de comportamientos concretos, no frases motivacionales abstractas)","hookOptions":["Mentalidad fija ante el fracaso: [X]. Mentalidad de crecimiento ante el mismo fracaso: [Y].", "Antes reaccionaba así ante los errores. Ahora reacciono de esta otra forma. El cambio fue gradual.", "No es un concepto de autoayuda. Es una forma de tomar decisiones que cambia resultados."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-GS-001","title":"El mapa mental de c\u00f3mo escala un SaaS","pillar":"business","series":"","objective":"authority","format":"green-screen","duration":"30–45s","hook":"Este es el mapa completo de c\u00f3mo escala un SaaS de cero a sus primeros clientes reales. Te lo explico frente a \u00e9l. (recomendado: fondo con diagrama de flujo o mapa mental del proceso, hecho en Miro, Figma o similar)","hookOptions":["Aquí está el roadmap que usé para pasar de idea a demo lista. Cada paso importa.", "Esto es lo que nadie te muestra del escalado de un SaaS porque nadie lo dibuja completo.", "El proceso de un SaaS no es lineal. Este diagrama lo hace visible. Te lo explico."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-GS-002","title":"C\u00f3mo funciona realmente una automatizaci\u00f3n","pillar":"automation","series":"","objective":"discovery","format":"green-screen","duration":"30–45s","hook":"Te voy a mostrar c\u00f3mo funciona una automatizaci\u00f3n por dentro. Sin tecnicismos. Con este diagrama detr\u00e1s de m\u00ed. (recomendado: fondo con diagrama de flujo real de una automatizaci\u00f3n simple, hecho en Make o Zapier vista de flows)","hookOptions":["Aquí está el flujo exacto que sigue una automatización de ventas. Cada paso que ves es real.", "Muchos hablan de automatización. Pocos te muestran cómo se ve por dentro. Esto es lo que hay.", "Este diagrama muestra en [X] pasos cómo una tarea que tardaba horas ahora tarda segundos."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-GS-003","title":"El ecosistema de IA que uso en mi startup","pillar":"ai","series":"","objective":"discovery","format":"green-screen","duration":"30–45s","hook":"Este es el ecosistema completo de herramientas de IA que usa mi startup. Te explico cada parte y para qu\u00e9 sirve. (recomendado: fondo con mapa visual de herramientas, conectadas por flujos, dise\u00f1o limpio en Figma o Notion)","hookOptions":["No todas las herramientas de IA que ves aquí cuestan dinero. La mayoría son gratuitas.", "Así se ve el stack de IA de una startup pequeña en [año actual]. Cada herramienta tiene su función.", "Si solo eligieras [X] herramientas de IA de este ecosistema, estas serían mis recomendadas."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-GS-004","title":"Mi proceso completo de creaci\u00f3n de contenido","pillar":"personal","series":"","objective":"discovery","format":"green-screen","duration":"30–45s","hook":"Aqu\u00ed est\u00e1 mi sistema completo de contenido, de la idea al reel publicado. Todo el proceso en un solo diagrama. (recomendado: fondo con flowchart del proceso, desde captura de idea hasta publicaci\u00f3n, con herramientas usadas en cada paso)","hookOptions":["De la idea al reel publicado: estos son los pasos exactos que sigo, sin omitir nada.", "Mi proceso de contenido no es inspiración. Es este sistema que te voy a explicar.", "Si quieres publicar [X] veces por semana sin agotarte, necesitas algo parecido a esto."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-GS-005","title":"El funnel de ventas de mi SaaS explicado","pillar":"business","series":"","objective":"authority","format":"green-screen","duration":"30–45s","hook":"Este es el funnel de ventas de mi SaaS. Te explico cada etapa y qu\u00e9 hace que alguien pase de extra\u00f1o a cliente. (recomendado: fondo con diagrama de funnel limpio, con m\u00e9tricas de conversi\u00f3n aproximadas por etapa cuando las tengas)","hookOptions":["Desde que alguien me ve en LinkedIn hasta que se convierte en cliente: estos son los pasos.", "Un funnel de ventas no es magia. Es un proceso diseñado. Aquí está el mío.", "Cada etapa de mi funnel tiene una tasa de conversión. Te muestro las mías con honestidad."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-GS-006","title":"El timeline de un fundador en a\u00f1o uno","pillar":"founder","series":"","objective":"connection","format":"green-screen","duration":"30–45s","hook":"Este es el timeline real de mis primeros [X] meses como fundador. Los hitos, las ca\u00eddas y los pivots, todos en una l\u00ednea de tiempo. (recomendado: fondo con l\u00ednea de tiempo visual, con fechas y hitos reales aunque simplificados)","hookOptions":["Mes uno: esto. Mes tres: esto otro. Mes seis: aquí fue el pivote. Te cuento cada punto.", "No fue una línea recta. Fue esto que ves detrás de mí. Y quiero explicarte cada curva.", "El primer año de una startup en una línea de tiempo honesta. No es el highlight reel."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-GS-007","title":"C\u00f3mo clasifico las noticias de IA para quedarme con lo que importa","pillar":"ai","series":"","objective":"authority","format":"green-screen","duration":"30–45s","hook":"Tengo un sistema para filtrar las noticias de IA y quedarme solo con lo que impacta mi trabajo. Te lo muestro. (recomendado: fondo con matriz 2x2 o sistema de clasificaci\u00f3n visual, como 'relevancia vs. urgencia')","hookOptions":["Esta matriz detrás de mí es cómo clasifico cada noticia de IA que leo. Te explico los cuadrantes.", "No toda noticia de IA merece atención. Este sistema me dice cuál sí y cuál no.", "Recibo [X] noticias de IA por semana. Solo [X] pasan mi filtro. Aquí está ese filtro."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-GS-008","title":"Los pilares de mi estrategia de contenido","pillar":"personal","series":"","objective":"authority","format":"green-screen","duration":"30–45s","hook":"Mi estrategia de contenido no es aleatoria. Est\u00e1 construida sobre estos pilares que te voy a explicar uno por uno. (recomendado: fondo con los pilares visualizados claramente, con ejemplos de tipos de contenido en cada uno)","hookOptions":["Sin pilares claros, el contenido no construye nada. Estos son los míos y por qué los elegí.", "Cada pieza de contenido que publico cae en uno de estos [X] pilares. Así es como funciona.", "La estrategia detrás de mi cuenta: estos son los temas, los objetivos y el por qué."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-GS-009","title":"El stack de automatizaci\u00f3n completo que uso","pillar":"automation","series":"","objective":"discovery","format":"green-screen","duration":"30–45s","hook":"Este es el stack completo de automatizaci\u00f3n de mi empresa. Cada herramienta tiene su funci\u00f3n y te voy a explicar el por qu\u00e9 de cada una. (recomendado: fondo con arquitectura visual de herramientas conectadas, tipo diagrama t\u00e9cnico simplificado)","hookOptions":["Usé [X] herramientas para automatizar [X] procesos en mi negocio. Aquí están todas y cómo se conectan.", "No se necesita ser técnico para implementar esto. El diagrama de atrás lo hace evidente.", "Este stack me libera [X] horas semanales. Te explico cada componente para que puedas replicarlo."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-GS-010","title":"El mapa del emprendedor: d\u00f3nde estoy y hacia d\u00f3nde voy","pillar":"founder","series":"","objective":"connection","format":"green-screen","duration":"30–45s","hook":"Aqu\u00ed est\u00e1 el mapa de mi viaje como fundador. No el que quer\u00eda. El que realmente est\u00e1 pasando. (recomendado: fondo con mapa de ruta honesto, con puntos de dolor y puntos de quiebre marcados visualmente)","hookOptions":["Dónde empecé, dónde estoy ahora y hacia dónde va todo esto. Te lo muestro con el mapa real.", "El plan original era este. Lo que está pasando de verdad es esto otro. Ambos en el mapa.", "Mi roadmap de fundador no es un pitch deck. Es un mapa con cicatrices. Y lo comparto hoy."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-GS-011","title":"Diagrama: c\u00f3mo toma decisiones la IA","pillar":"ai","series":"","objective":"discovery","format":"green-screen","duration":"30–45s","hook":"\u00bfC\u00f3mo decide la IA qu\u00e9 respuesta darte? Te lo explico con este diagrama simplificado. No necesitas ser t\u00e9cnico para entenderlo. (recomendado: fondo con diagrama de flujo de c\u00f3mo funciona un LLM de forma simplificada, visualmente claro)","hookOptions":["Detrás de cada respuesta de la IA hay un proceso. Este diagrama lo hace visible.", "Entender cómo funciona la IA cambia cómo le haces preguntas. Empieza aquí.", "Sin entrar en matemáticas: así es cómo procesa tu pregunta un modelo de lenguaje."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-GS-012","title":"La pir\u00e1mide de prioridades del emprendedor","pillar":"business","series":"","objective":"authority","format":"green-screen","duration":"30–45s","hook":"No todas las tareas de un emprendedor pesan igual. Esta pir\u00e1mide detr\u00e1s de m\u00ed lo explica visualmente. (recomendado: fondo con pir\u00e1mide de prioridades, donde la base son las tareas de mayor impacto y la cima las de menor)","hookOptions":["Si estás confundido sobre en qué trabajar, este marco te ordena el caos.", "La mayoría del tiempo de un emprendedor va a la base de la pirámide. El problema es cuál es la base.", "Esta pirámide cambió cómo planeo mi semana. Aquí está cómo usarla."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-GS-013","title":"El ciclo del contenido que genera comunidad","pillar":"personal","series":"","objective":"authority","format":"green-screen","duration":"30–45s","hook":"El contenido no es solo publicar. Es un ciclo que, cuando funciona bien, genera comunidad sola. Aqu\u00ed est\u00e1 ese ciclo. (recomendado: fondo con ciclo visual: idea \u2192 contenido \u2192 comunidad \u2192 feedback \u2192 nueva idea, con flechas claras)","hookOptions":["Este ciclo detrás de mí es lo que diferencia a las cuentas que crecen de las que publican y nada.", "Publicar sin estrategia es ruido. Este ciclo convierte el contenido en algo que construye.", "La comunidad no se pide. Se genera con este proceso. Aquí está cada etapa."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-GS-014","title":"El modelo de negocio de mi SaaS en un diagrama","pillar":"founder","series":"","objective":"authority","format":"green-screen","duration":"30–45s","hook":"Aqu\u00ed est\u00e1 el modelo de negocio completo de mi SaaS. No el pitch deck. El modelo real de c\u00f3mo entra el dinero. (recomendado: fondo con Business Model Canvas simplificado o diagrama de flujo de ingresos y costos reales)","hookOptions":["De dónde viene el dinero, a dónde va y qué hace que el modelo sea sostenible. Todo aquí.", "No hay misterio en cómo funciona un SaaS. Este diagrama lo desmitifica.", "El modelo de negocio que construí: estas son las palancas que lo hacen o lo rompen."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-GS-015","title":"C\u00f3mo constru\u00ed mi marca personal con un diagrama","pillar":"personal","series":"","objective":"authority","format":"green-screen","duration":"30–45s","hook":"Mi marca personal no surgi\u00f3 sola. Fue dise\u00f1ada. Y este diagrama muestra el proceso exacto. (recomendado: fondo con mapa de posicionamiento o estrategia de marca: valores, audiencia, diferenciaci\u00f3n, canales)","hookOptions":["Aquí están los [X] elementos que definieron mi marca personal y cómo los construí.", "El posicionamiento no es un concepto vago. Es estas decisiones concretas que ves detrás.", "Sin este marco, mi marca no tendría coherencia. Aquí está para que lo uses tú también."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-GS-016","title":"El flujo de trabajo con IA que uso cada ma\u00f1ana","pillar":"ai","series":"","objective":"discovery","format":"green-screen","duration":"30–45s","hook":"Cada ma\u00f1ana sigo este flujo de trabajo que incluye IA en [X] puntos clave. Te lo explico con el diagrama. (recomendado: fondo con timeline de la rutina matutina, se\u00f1alando en qu\u00e9 momentos espec\u00edficos entra la IA)","hookOptions":["Mi primera hora de trabajo incluye IA en estas [X] tareas concretas. Aquí están.", "De 8 a 9am hago todo esto con IA. Así se ve el flujo real detrás de mí.", "Integrar IA en tu rutina no es complicado si tienes un flujo. Este es el mío."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-GS-017","title":"El diagrama del emprendedor funcional vs. ocupado","pillar":"business","series":"","objective":"authority","format":"green-screen","duration":"30–45s","hook":"Estos dos organigramas representan dos tipos de emprendedor. Uno escala. El otro se agota. \u00bfCu\u00e1l eres t\u00fa? (recomendado: fondo con dos organigramas contrastantes, uno centralizado en el fundador y otro con sistemas delegados)","hookOptions":["El emprendedor que lo hace todo vs. el que construye sistemas. Aquí está la diferencia visual.", "Si todo en tu empresa pasa por ti, este diagrama describe por qué no puedes escalar.", "El momento en que dejé de ser el cuello de botella de mi empresa fue cuando entendí esto."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-GS-018","title":"El mapa de decisiones del fundador en etapa temprana","pillar":"founder","series":"","objective":"authority","format":"green-screen","duration":"30–45s","hook":"\u00bfC\u00f3mo saber qu\u00e9 hacer primero en una startup? Este \u00e1rbol de decisiones detr\u00e1s de m\u00ed lo resuelve. (recomendado: fondo con \u00e1rbol de decisiones para prioridades en etapa early: producto vs. ventas vs. marketing vs. operaciones)","hookOptions":["Cuando no sé qué hacer primero en mi startup, uso este árbol. Te explico cómo funciona.", "No todas las decisiones de un fundador tienen el mismo peso. Este diagrama te ayuda a verlo.", "El mapa de decisiones que me hubiera ahorrado [X] meses de confusión en el año uno."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-GS-019","title":"C\u00f3mo mapeo una nueva automatizaci\u00f3n antes de construirla","pillar":"automation","series":"","objective":"discovery","format":"green-screen","duration":"30–45s","hook":"Antes de construir cualquier automatizaci\u00f3n, la dibujo. Este es el mapa que hago siempre primero. (recomendado: fondo con plantilla de dise\u00f1o de automatizaci\u00f3n: trigger \u2192 acci\u00f3n \u2192 condici\u00f3n \u2192 resultado)","hookOptions":["El error más común al automatizar es empezar a conectar herramientas sin mapear el proceso.", "Esta plantilla de detrás es lo que uso siempre antes de abrir Make o Zapier.", "Mapear antes de construir te ahorra [X] horas de debugging. Así se hace."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-GS-020","title":"El ciclo de aprendizaje del emprendedor moderno","pillar":"personal","series":"","objective":"connection","format":"green-screen","duration":"30–45s","hook":"Los emprendedores que crecen m\u00e1s r\u00e1pido no son los que m\u00e1s trabajan. Son los que aprenden con este ciclo. (recomendado: fondo con ciclo de aprendizaje acelerado: acci\u00f3n \u2192 observaci\u00f3n \u2192 reflexi\u00f3n \u2192 ajuste \u2192 acci\u00f3n)","hookOptions":["Aprender rápido no es leer más libros. Es este ciclo que te voy a explicar con el diagrama.", "El ciclo que uso para convertir errores en aprendizajes en menos de [X] días.", "La diferencia entre un emprendedor que crece y uno que se estanca está en esta fase del ciclo."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-GS-021","title":"El landscape de herramientas de IA para founders","pillar":"ai","series":"","objective":"discovery","format":"green-screen","duration":"30–45s","hook":"Hay demasiadas herramientas de IA para emprendedores. Este landscape te ayuda a orientarte sin perderte. (recomendado: fondo con landscape visual categorizado: IA para contenido, ventas, operaciones, producto, an\u00e1lisis)","hookOptions":["Categoricer las herramientas de IA te evita caer en el FOMO permanente de herramientas.", "No necesitas todas estas herramientas. Pero sí necesitas saber qué existe en cada categoría.", "Este mapa de IA para founders te ayuda a elegir las [X] que más impactan tu etapa actual."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-GS-022","title":"La arquitectura de un sistema de ventas automatizado","pillar":"automation","series":"","objective":"authority","format":"green-screen","duration":"30–45s","hook":"Un sistema de ventas automatizado no es un solo flujo. Es esta arquitectura. Te la explico pieza por pieza. (recomendado: fondo con arquitectura de sistema: LinkedIn \u2192 CRM \u2192 email \u2192 follow-up \u2192 cierre, con herramientas espec\u00edficas en cada nodo)","hookOptions":["Detrás de cada lead que convierte hay un sistema diseñado. Este es el mío.", "No hay magia en las ventas automatizadas. Hay esta arquitectura que cualquiera puede construir.", "Te muestro cómo conectar [X] herramientas para que tus ventas funcionen solas."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-GS-023","title":"El cronograma real de lanzar un SaaS","pillar":"founder","series":"","objective":"authority","format":"green-screen","duration":"30–45s","hook":"Si est\u00e1s pensando en lanzar un SaaS, este cronograma real te va a dar una perspectiva que ning\u00fan tutorial te da. (recomendado: fondo con Gantt chart o timeline con etapas reales: validaci\u00f3n, MVP, beta, lanzamiento, iteraci\u00f3n)","hookOptions":["El cronograma de lanzamiento que nadie te muestra porque no es lineal ni bonito.", "Realista: así son los tiempos reales de un SaaS en etapa temprana. Sin romantizar.", "Si crees que lanzarás en [X] semanas, este cronograma va a recalibrar tus expectativas."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-GS-024","title":"Mi framework personal de toma de decisiones","pillar":"personal","series":"","objective":"authority","format":"green-screen","duration":"30–45s","hook":"Cuando tengo que tomar una decisi\u00f3n dif\u00edcil, uso este framework. Te lo explico con el diagrama detr\u00e1s. (recomendado: fondo con framework visual de decisi\u00f3n: criterios, opciones, peso, resultado esperado, alineaci\u00f3n con valores)","hookOptions":["No tomo decisiones importantes de cabeza. Las proceso con este sistema que ves detrás.", "El framework que uso para decisiones de negocio tiene [X] preguntas clave. Estas son.", "Antes de elegir, paso por este proceso. Me ha salvado de más de un error costoso."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-GS-025","title":"El modelo de ingresos de un creador de contenido con IA","pillar":"ai","series":"","objective":"authority","format":"green-screen","duration":"30–45s","hook":"Hay [X] formas en que un creador puede monetizar con IA hoy. Este diagrama las muestra todas y cu\u00e1l es la m\u00e1s accesible. (recomendado: fondo con \u00e1rbol de monetizaci\u00f3n para creadores que usan IA: servicio, producto, educaci\u00f3n, afiliados)","hookOptions":["Monetizar con IA no es un mito. Son estas [X] vías reales que puedes empezar hoy.", "De todas las formas de generar ingresos con IA, esta es la más rápida para empezar.", "Este diagrama muestra cómo la IA puede convertirse en una fuente de ingreso real en tu negocio."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-GS-026","title":"El diagrama del problema que resuelve mi startup","pillar":"business","series":"","objective":"authority","format":"green-screen","duration":"30–45s","hook":"Este diagrama muestra exactamente el problema que mi startup resuelve. No el elevator pitch. La realidad del dolor del cliente. (recomendado: fondo con mapa del problema: situaci\u00f3n actual del cliente \u2192 puntos de dolor \u2192 soluci\u00f3n \u2192 resultado esperado)","hookOptions":["Así se ve el problema que resolvemos cuando lo dibujamos. Y así encaja nuestra solución.", "Ningún pitch deck te da esta claridad. Un diagrama de problema sí. Aquí está el mío.", "El cliente no sabe que tiene este problema hasta que lo ve dibujado. Eso es lo que hacemos."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-GS-027","title":"C\u00f3mo funciona mi flujo de leads en LinkedIn","pillar":"business","series":"","objective":"discovery","format":"green-screen","duration":"30–45s","hook":"Mi flujo de generaci\u00f3n de leads en LinkedIn de principio a fin. Sin herramientas de pago. Con este proceso visual. (recomendado: fondo con flujo de LinkedIn: perfil optimizado \u2192 contenido \u2192 conexi\u00f3n \u2192 conversaci\u00f3n \u2192 demo)","hookOptions":["Así consigo demos desde LinkedIn sin hacer spam. El proceso completo en este diagrama.", "De publicar contenido a tener una demo agendada: estos son los pasos reales.", "No es magia. Es este proceso. Y cualquiera puede replicarlo con consistencia."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-GS-028","title":"El mapa de fuentes de informaci\u00f3n que uso para IA","pillar":"ai","series":"","objective":"authority","format":"green-screen","duration":"30–45s","hook":"Hay mucho ruido sobre IA. Estas son mis fuentes reales para mantenerme actualizado sin perder horas. El mapa completo aqu\u00ed. (recomendado: fondo con mapa de fuentes: newsletters, X/Twitter cuentas, podcasts, papers \u2192 categorizadas por profundidad)","hookOptions":["De todas las fuentes de IA que existen, estas [X] son las que realmente uso y recomiendo.", "Mi rutina de consumo de información sobre IA: estas son las fuentes, el tiempo y el formato.", "Para estar actualizado en IA sin volverse loco, necesitas este mapa de fuentes confiables."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-GS-029","title":"El diagrama del emprendedor en modo construcci\u00f3n","pillar":"founder","series":"","objective":"connection","format":"green-screen","duration":"30–45s","hook":"Esto es lo que se ve cuando un fundador est\u00e1 en modo construcci\u00f3n real. No el glamour. La realidad de los sistemas activos. (recomendado: fondo con kanban board real o tablero de sprints, con tareas reales aunque simplificadas)","hookOptions":["Mi tablero de trabajo en la fase actual de mi startup. Te explico qué hay en cada columna.", "Así se ve el trabajo real de construir un producto, no el pitch. Este es mi sistema.", "Cuando digo que estoy construyendo, esto es literalmente lo que significa. Te lo muestro."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""},
{"id":"H-GS-030","title":"La curva de aprendizaje real de un fundador t\u00e9cnico","pillar":"founder","series":"","objective":"connection","format":"green-screen","duration":"30–45s","hook":"Si eres t\u00e9cnico y fundas una empresa, hay una curva de aprendizaje que nadie te advierte. Esta es la m\u00eda visualizada. (recomendado: fondo con gr\u00e1fico de curva real: t\u00e9cnico \u2192 producto \u2192 ventas \u2192 operaciones, con los valles de incompetencia marcados)","hookOptions":["Sabía construir el producto. No sabía vender, operar ni escalar. Esta curva lo resume.", "Cada valle en esta curva representa algo que tuve que aprender de cero siendo fundador técnico.", "Si estás en uno de estos valles, esta curva te va a dar perspectiva de que es normal."],"body":"","payoff":"","cta":"","status":"ready","review":"","sourceStoryId":""}],firstBatch:[2,7,8,9,10].map((n,i)=>({id:`stage1-hook-${n}`,hookNumber:n,title:`Hook ${n} · texto pendiente`,status:'to_publish',script:'',publishedAt:null,reviewed:false}))}, userData=null, activeView='metrics',toastTimer=null, dataKey=null, promptSeed='';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const localDate=()=>new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,10);
function notify(msg){const t=$('#toast');if(!t)return;t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2400)}
async function deriveKey(password,salt){const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:180000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function loadLocal(key){const raw=localStorage.getItem(KEYS.data);if(!raw)return null;const box=JSON.parse(raw),iv=Uint8Array.from(atob(box.iv),c=>c.charCodeAt(0)),data=Uint8Array.from(atob(box.data),c=>c.charCodeAt(0));const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv},key,data);return JSON.parse(new TextDecoder().decode(plain))}
async function save(){if(!dataKey)return;const iv=crypto.getRandomValues(new Uint8Array(12)),cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},dataKey,new TextEncoder().encode(JSON.stringify(userData)));localStorage.setItem(KEYS.data,JSON.stringify({v:1,iv:b64(iv),data:b64(cipher)}));renderAll()}
function initLocal(x=null){userData=x||{stories:[],firstBatch:structuredClone(baseData.firstBatch||[]),scripts:structuredClone(baseData.scripts||[]),metrics:[],customIdeas:[]};}
async function sha(text,salt){const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(text),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt,iterations:180000,hash:'SHA-256'},key,256);return [...new Uint8Array(bits)].map(b=>b.toString(16).padStart(2,'0')).join('')}
function b64(bytes){return btoa(String.fromCharCode(...new Uint8Array(bytes)))}
async function enterStudio(){const known=localStorage.getItem(KEYS.salt);$('#lockTitle').innerHTML=known?'Tu estudio<br><span>de contenido.</span>':'Configura tu<br><span>clave local.</span>';$('#lockCopy').textContent=known?'Ingresa tu clave local para abrir el panel en este dispositivo.':'Elige una clave local para proteger el panel en este dispositivo. Tus guiones y métricas se cifran aquí y no se suben a una base de datos.';$('#lockSubmit').innerHTML=known?'Desbloquear estudio <span>→</span>':'Crear clave y entrar <span>→</span>';$('#localPin').setAttribute('autocomplete',known?'current-password':'new-password');}
function showApp(){ $('#lockScreen').classList.add('hidden');$('#studioApp').classList.remove('hidden');renderAll();setView(activeView)}
function setView(v){activeView=v;$$('.side-link').forEach(b=>b.classList.toggle('selected',b.dataset.view===v));renderView()}
function allStories(){return [...userData.stories,...(userData.customIdeas||[])]}
function pillarName(p){return ({business:'Emprendimiento y negocios',personal:'Desarrollo personal',ai:'IA aplicada',automation:'Automatización y sistemas',founder:'Proceso del fundador',unclassified:'Sin clasificar'})[p]||'Sin clasificar'}
