function ideasView(){const stories=allStories();return `<section class="view-panel"><p class="eyebrow">MATERIA PRIMA · EXPERIENCIAS Y APRENDIZAJES REALES</p><h2>Captura tus momentos</h2><p class="subcopy">Guarda experiencias reales en una frase; luego podrás convertirlas en guiones para Reels, TikTok o historias. Las historias llevan fuente y pendientes. Completa los vacíos con tu recuerdo antes de convertirlas en guion. “Revisar” marca contenido que no debe publicarse todavía.</p><form id="quickCapture" class="quick-capture-inline"><input id="captureTitle" required maxlength="110" placeholder="¿Qué pasó? (ej. Probé una automatización y falló)"><textarea id="captureNote" rows="2" placeholder="Qué hiciste, qué pasó y qué aprendiste"></textarea><select id="capturePillar"><option value="business">Emprendimiento y negocios</option><option value="ai">IA aplicada</option><option value="automation">Automatización y sistemas</option><option value="personal">Desarrollo personal</option></select><button class="button button-lime" type="submit">Guardar historia ＋</button></form><div class="toolbar"><select id="ideaPillarFilter"><option value="all">Todos los pilares</option><option value="business">Emprendimiento y negocios</option><option value="ai">IA aplicada</option><option value="automation">Automatización y sistemas</option><option value="personal">Desarrollo personal</option><option value="founder">Proceso del fundador</option></select><select id="ideaStatusFilter"><option value="all">Todos los estados</option><option value="needs_review">Revisar</option><option value="needs_details">Ampliar</option><option value="idea">Listas para trabajar</option></select><button class="button button-outline" id="newStory">＋ Capturar historia</button></div><div id="storyList">${stories.map(storyCard).join('')}</div></section>`}
const storyTemplates=[
  {id:'day',title:'Un momento de hoy',goal:'Cercanía · 4 historias',frames:['1 · Muestra dónde estás o qué estás haciendo.','2 · ¿Qué está pasando? Cuéntalo en una frase.','3 · ¿Qué pensaste o sentiste de verdad?','4 · Cierra con una pregunta sencilla para conversar.']},
  {id:'lesson',title:'Algo que aprendí',goal:'Aprendizaje · 3 historias',frames:['1 · “Antes pensaba que…”','2 · “Me pasó esto y me hizo cambiar de opinión…”','3 · “Ahora estoy probando… ¿te ha pasado?”']},
  {id:'behind',title:'Detrás del proceso',goal:'Proceso · 4 historias',frames:['1 · Enseña el problema o la tarea real.','2 · Cuenta qué intentaste.','3 · Muestra el resultado, aunque no haya salido perfecto.','4 · Encuesta: “¿Qué probarías tú?”']},
  {id:'question',title:'Pregunta a la comunidad',goal:'Conversación · 3 historias',frames:['1 · Comparte una decisión o duda real.','2 · Añade contexto corto y dos opciones.','3 · Usa encuesta/preguntas y vuelve después a comentar respuestas.']},
  {id:'build',title:'Construyendo algo',goal:'Serie opcional del SaaS · 4 historias',frames:['1 · “Hoy estoy intentando resolver…”','2 · Muestra una parte del proceso sin datos de clientes.','3 · Cuenta qué decisión tomaste y por qué.','4 · “¿Qué harías distinto?”']}
];
function inspirationView(){return `<section class="view-panel"><p class="eyebrow">INSPIRACIÓN PARA REELS Y TIKTOK</p><h2>Una idea empieza con algo que viviste.</h2><p class="subcopy">En tu perfil actual ya aparece contenido de ambición, rechazo, disciplina y propósito. Úsalo como puente hacia tus experiencias propias: construir, aprender, probar IA y cambiar hábitos.</p><div class="inspiration-grid">${[
{pillar:'personal',tag:'DESARROLLO PERSONAL',title:'De la frase a la historia real',body:'¿Qué situación te hizo pensar en rechazo, vergüenza, disciplina o propósito? Cuenta qué pasó contigo, no solo la frase que te inspiró.',hook:'“Yo también pensaba que [creencia], hasta que me pasó esto…”'},
{pillar:'business',tag:'EMPRENDIMIENTO',title:'Lo que no se ve al construir',body:'Una decisión pequeña, una duda, un error concreto o algo que cambiaste esta semana.',hook:'“Esto es lo que nadie me explicó antes de intentar construir un negocio…”'},
{pillar:'ai',tag:'IA APLICADA',title:'La IA en una tarea de verdad',body:'Enseña qué tarea intentaste resolver, qué resultado dio y qué tuviste que corregir.',hook:'“Probé IA para [tarea] y esto fue lo que sí/no me ahorró…”'},
{pillar:'automation',tag:'AUTOMATIZACIÓN',title:'Antes y después de un proceso',body:'Parte de una repetición o fricción real. Cuenta qué automatizaste y qué sigue siendo manual.',hook:'“Esta tarea se repetía tanto que decidí automatizarla. Así lo pensé…”'},
{pillar:'founder',tag:'PROCESO PERSONAL',title:'Ambición con los pies en la tierra',body:'Conecta tus motivos para construir con lo que estás viviendo hoy, sin convertirlo en una promesa de éxito.',hook:'“Quiero construir algo grande, pero esta semana el paso real fue…”'},
{pillar:'business',tag:'APRENDIZAJE',title:'Una idea que cambió al probarla',body:'Comparte qué esperabas, qué ocurrió y qué harás distinto. Funciona con negocios, vida, IA o hábitos.',hook:'“Creía que [suposición]. Lo probé y pasó esto…”'}
].map(x=>`<article class="inspiration-card"><span class="story-meta">${x.tag}</span><h3>${x.title}</h3><p>${x.body}</p><p class="inspiration-hook">${x.hook}</p><button class="text-button use-inspiration" data-pillar="${x.pillar}" data-hook="${esc(x.hook)}">Usar como punto de partida ↗</button></article>`).join('')}</div><div class="panel-card prompt-builder"><div class="panel-heading"><div><p class="eyebrow">GENERAR LOTE</p><h2>Preparar guiones con el asistente</h2></div></div><p class="muted-intro">Elige cantidad y temas. El pedido incluye tus historias guardadas que no estén marcadas como sensibles. La generación ocurre en el chat, sin API de pago.</p><div class="toolbar"><label>CANTIDAD <input id="generationCount" type="number" min="1" max="20" value="8" style="width:75px"></label><label>PILAR <select id="generationPillar"><option value="mix">Mezcla de pilares</option><option value="business">Emprendimiento y negocios</option><option value="ai">IA aplicada</option><option value="automation">Automatización y sistemas</option><option value="personal">Desarrollo personal</option><option value="founder">Proceso del fundador</option></select></label><button class="button button-outline" id="generatePrompt">Preparar pedido</button><button class="button button-outline" id="copyGenerationPrompt">Copiar pedido</button></div><textarea id="generationPrompt" rows="10" readonly placeholder="El pedido aparecerá aquí."></textarea></div></section>`}
function storiesFormatView(){return `<section class="view-panel"><p class="eyebrow">SECUENCIAS PARA INSTAGRAM STORIES</p><h2>Guiones simples para historias</h2><p class="subcopy">Toma una secuencia, completa los espacios con lo que realmente pasó y publícala. No hace falta que cada historia sea una venta ni que todo trate del SaaS.</p><div class="inspiration-grid">${storyTemplates.map(t=>`<article class="inspiration-card story-template"><span class="story-meta">${t.goal}</span><h3>${t.title}</h3><ol>${t.frames.map(f=>`<li>${esc(f)}</li>`).join('')}</ol><button class="text-button copy-story-template" data-id="${t.id}">Copiar formato ↗</button></article>`).join('')}</div></section>`}
function storyCard(s){return `<article class="story-card" data-pillar="${esc(s.pillar)}" data-status="${esc(s.status)}"><span class="story-id">${esc(s.id)}</span><div><h3>${esc(s.title)}</h3><p>${esc(s.facts||s.note||'')}</p><p><b style="color:#ddd">Decisión/acción:</b> ${esc(s.action||'Pendiente de completar')}</p><div class="story-meta">FUENTE ${esc(s.source||'CAPTURA')} · ${pillarName(s.pillar).toUpperCase()}</div>${s.review?`<p style="color:#e5a276;margin-top:8px">Pendiente: ${esc(s.review)}</p>`:''}<textarea class="story-notes" data-id="${esc(s.id)}" placeholder="Completa o corrige con tus palabras; se guarda en este navegador." rows="2">${esc(s.userNotes||'')}</textarea><button class="text-button save-note" data-id="${esc(s.id)}">Guardar contexto ↗</button></div><span class="story-tag ${s.sensitive||s.status==='needs_review'?'review':''}">${s.status==='needs_review'||s.sensitive?'REVISAR':s.status==='needs_details'?'AMPLIAR':'IDEA'}</span></article>`}
function buildGenerationPrompt(){const out=$('#generationPrompt');if(!out)return;const count=Math.max(1,Math.min(20,Number($('#generationCount')?.value)||8)),p=$('#generationPillar')?.value||'mix';const stories=allStories().filter(x=>x.status!=='needs_review'&&!x.sensitive).filter(x=>p==='mix'||x.pillar===p).slice(0,30).map(x=>({id:x.id,title:x.title,pillar:pillarName(x.pillar),facts:x.facts||x.note||'',action:x.action||'',outcome:x.outcome||'',learning:x.learning||'',notes:x.userNotes||''}));const selected=stories;out.value=`Actúa como guionista de mi MARCA PERSONAL para Reels y TikTok. No escribas como cuenta corporativa ni hagas que todo trate del SaaS.

CONTEXTO: Soy Benja Romero. Quiero conectar mostrando el proceso real de emprender y de crecer como persona. Mis temas son emprendimiento y negocios (incluye mi SaaS como una serie, no como identidad completa), desarrollo personal, IA aplicada y automatización/sistemas. Hablo a cámara. Referencias de ritmo/claridad: Alejo Muñoz, Emilio Axis y Daniel Dalen; encuentra una voz propia, sin imitar frases. Mi prioridad es conexión y aprendizaje; el interés comercial es ocasional y nunca forzado.

ENCARGO: Genera ${count} videos de 20–60 segundos. Enfoque: ${p==='mix'?'mezcla equilibrada y variada de todos los pilares':pillarName(p)}. Si elijo mezcla, incluye varios pilares y evita concentrarlos todos en SaaS. ${promptSeed?`PUNTO DE PARTIDA ELEGIDO: ${promptSeed}. Desarróllalo sin asumir que ya ocurrió algo específico; si necesita una experiencia, deja la pregunta en review.`:''} Alterna historias vulnerables, aprendizajes útiles, decisiones, errores, observaciones, IA/automatización aplicada y preguntas que abran conversación. Prioriza hechos reales del contexto; no inventes hitos, cifras, clientes ni sentimientos. Si falta información, formula guiones honestos que no presupongan datos y deja preguntas concretas en review. Cada pieza debe sonar hablada y natural: gancho específico, contexto/momento, tensión o giro, aprendizaje/conclusión, CTA breve opcional. Entrega hooks alternativos (3) por video. Nada de promesas de viralidad ni clickbait engañoso.

HISTORIAS CONFIRMADAS DISPONIBLES:
${JSON.stringify(selected,null,2)}

Devuelve SOLO JSON válido en este formato, sin markdown: {"scripts":[{"id":"idea-01","title":"...","pillar":"business|personal|ai|automation|founder","objective":"connection|discovery|authority|conversion","format":"hablar-a-camara","duration":"30-45s","hook":"...","hookOptions":["...","...","..."],"body":"...","payoff":"...","cta":"...","status":"ready","review":"...","sourceStoryId":"..."}]}. Usa conversion solo si una pieza menciona de forma natural que existe el SaaS/producto. La serie SaaS puede usar series:"saas_build" y stage solo si aplica. No inventes la fase activa: pregúntame o deja stage sin asignar. No cargues datos privados de clientes.`}
function scriptsView(){return `<section class="view-panel"><p class="eyebrow">GUIONES · MARCA PERSONAL</p><h2>Guiones y piezas</h2><p class="subcopy">Pídele al asistente un paquete de contenidos y cárgalo aquí. Las piezas se guardan cifradas en este navegador. El SaaS puede tener una serie por etapas; IA, automatización, negocios y desarrollo personal siguen su propio ritmo.</p><div class="toolbar"><button class="button button-lime" id="newScript">＋ Crear borrador</button><button class="button button-outline" id="exportProduction">Exportar producción</button><button class="button button-outline" id="importProduction">Importar JSON desde archivo</button><input id="productionFile" type="file" accept="application/json" hidden></div><label for="packageJson" class="story-meta">PAQUETE DEL ASISTENTE · JSON</label><textarea id="packageJson" rows="7" placeholder='{"stage":1,"scripts":[{"id":"pieza-01","title":"Título","pillar":"business","stage":1,"duration":"30-45s","hook":"Gancho","body":"Contexto y tensión","payoff":"Qué pasó / aprendizaje","cta":"","status":"ready","review":""}]}'></textarea><button class="button button-outline" id="loadPackage">Cargar piezas al Estudio <span>→</span></button><p class="muted-intro" style="margin-top:10px">Esto las agrega a tu cola privada de producción; no las publica en Instagram. No incluyas datos sensibles en un paquete.</p><div id="scriptList" style="margin-top:18px">${userData.scripts.map(scriptCard).join('')||'<p class="muted-intro">Aún no hay borradores nuevos. Genera contenido desde las historias reales, sin limitar los pilares a la serie del SaaS.</p>'}</div><h3 style="font-size:12px;margin:26px 0 10px">Registro de la primera tanda</h3>${userData.firstBatch.map((v,i)=>`<article class="script-card"><div style="display:flex;justify-content:space-between;gap:12px"><div><h3>Video 0${i+1} · Hook ${v.hookNumber}</h3><p class="muted-intro">${esc(v.title)} · ${v.publishedAt?'Publicado '+esc(v.publishedAt):'A publicar'}</p></div><span class="story-tag">${v.reviewed?'REVISADO':v.status==='published'?'MEDIR':'PENDIENTE'}</span></div><textarea data-batch="${esc(v.id)}" class="batch-script" rows="2" placeholder="Pega aquí el texto original del hook o el guion si lo tienes.">${esc(v.script||'')}</textarea><div class="script-actions"><select data-batch-status="${esc(v.id)}"><option value="to_publish" ${v.status==='to_publish'?'selected':''}>Por publicar</option><option value="published" ${v.status==='published'?'selected':''}>Publicado</option></select><label style="font-size:9px;color:#aaa">Fecha <input type="date" data-batch-date="${esc(v.id)}" value="${esc(v.publishedAt||'')}" style="background:#11120f;color:#ccc;border:1px solid #393a32;padding:6px"></label><label style="font-size:9px;color:#aaa"><input type="checkbox" data-batch-review="${esc(v.id)}" ${v.reviewed?'checked':''}> Resultado revisado</label></div></article>`).join('')}<div style="margin-top:15px"><button class="button button-outline" id="saveBatch">Guardar primera tanda</button></div></section>`}
function scriptCard(s){return `<article class="script-card"><div style="display:flex;justify-content:space-between;gap:14px"><div><h3>${esc(s.title)}</h3><div class="story-meta">${pillarName(s.pillar).toUpperCase()} · ${esc(s.format||'hablar-a-camara')} · ${esc(s.duration||'30–45s')}</div></div><select data-script-status="${esc(s.id)}"><option value="draft" ${s.status==='draft'?'selected':''}>Borrador</option><option value="ready" ${s.status==='ready'?'selected':''}>Listo para grabar</option><option value="production" ${s.status==='production'?'selected':''}>En producción</option><option value="published" ${s.status==='published'?'selected':''}>Publicado</option></select></div><div class="script-body"><div class="script-beat"><b>GANCHO</b><textarea data-script-field="hook" data-id="${esc(s.id)}">${esc(s.hook||'')}</textarea>${(s.hookOptions||[]).length?`<div class="hook-options">${s.hookOptions.map((h,i)=>`<button type="button" class="text-button use-hook" data-id="${esc(s.id)}" data-hook="${i}">Usar alternativa ${i+1}: ${esc(h)}</button>`).join('')}</div>`:''}</div><div class="script-beat"><b>MOMENTO REAL / CONTEXTO</b><textarea data-script-field="body" data-id="${esc(s.id)}">${esc(s.body||'')}</textarea></div><div class="script-beat"><b>DECISIÓN, RESULTADO O APRENDIZAJE</b><textarea data-script-field="payoff" data-id="${esc(s.id)}">${esc(s.payoff||'')}</textarea></div><div class="script-beat"><b>CTA (A DEFINIR POR BENJA)</b><textarea data-script-field="cta" data-id="${esc(s.id)}">${esc(s.cta||'')}</textarea></div></div><div class="script-actions"><span class="story-meta">${s.review?'⚠ REVISAR HECHOS ANTES DE PUBLICAR':'HECHOS POR CONFIRMAR POR BENJA'}</span><button class="text-button delete-script" data-id="${esc(s.id)}">Quitar borrador</button></div></article>`}
function getMetrics(){return userData.metrics||[]}
function rates(m){const reach=Number(m.reach)||0,duration=Number(m.duration)||0,watch=Number(m.avgWatch)||0,interactions=(Number(m.likes)||0)+(Number(m.comments)||0)+(Number(m.shares)||0)+(Number(m.saves)||0);return {engagement:reach?100*interactions/reach:0,save:reach?100*(Number(m.saves)||0)/reach:0,share:reach?100*(Number(m.shares)||0)/reach:0,comment:reach?100*(Number(m.comments)||0)/reach:0,watch:duration?100*watch/duration:0,follow:reach?100*(Number(m.followersGained)||0)/reach:0,profile:reach?100*(Number(m.profileVisits)||0)/reach:0,lead:reach?100*(Number(m.inquiries)||0)/reach:0}}
function fmt(n,d=1){return `${Number(n||0).toFixed(d)}%`}
function metricWindow(){const days=Number($('#metricWindow')?.value??15);if(!days)return getMetrics();const cutoff=new Date();cutoff.setDate(cutoff.getDate()-days);const key=cutoff.toISOString().slice(0,10);return getMetrics().filter(m=>(m.date||'')>=key)}
function metricsView(){const all=getMetrics(),ms=metricWindow(),sum=k=>ms.reduce((a,m)=>a+(Number(m[k])||0),0),mean=k=>ms.length?ms.reduce((a,m)=>a+(rates(m)[k]||0),0)/ms.length:0,top=[...ms].sort((a,b)=>rates(b).follow-rates(a).follow)[0],groupKeys=[...new Set(ms.map(m=>`${m.platform||'instagram'}::${m.pillar||'unclassified'}`))],groups=groupKeys.map(key=>{const [platform,p]=key.split('::'),items=ms.filter(m=>(m.platform||'instagram')===platform&&(m.pillar||'unclassified')===p),reach=items.reduce((a,m)=>a+(Number(m.reach)||0),0),followers=items.reduce((a,m)=>a+(Number(m.followersGained)||0),0),comments=items.reduce((a,m)=>a+(Number(m.comments)||0),0),shares=items.reduce((a,m)=>a+(Number(m.shares)||0),0);return {platform,p,count:items.length,reach,followers,comments,shares,followRate:reach?100*followers/reach:0,connectionRate:reach?100*(comments+shares)/reach:0}});return `<section class="view-panel"><p class="eyebrow">DECIDIR CON TUS PROPIOS DATOS</p><h2>¿Qué está conectando?</h2><p class="subcopy">Revisa cada 15 días. Compara temas y ganchos con tu propio histórico. Instagram puede sincronizarse al conectar Meta; TikTok se registra manualmente por ahora.</p><div class="toolbar"><label class="story-meta">PERIODO <select id="metricWindow"><option value="15" ${$('#metricWindow')?.value==='15'?'selected':''}>Últimos 15 días</option><option value="30" ${$('#metricWindow')?.value==='30'?'selected':''}>Últimos 30 días</option><option value="0" ${$('#metricWindow')?.value==='0'?'selected':''}>Todo el histórico</option></select></label><span class="api-badge" id="igStatus">REVISAR CONEXIÓN</span><button class="button button-outline" id="connectIg">Conectar Instagram</button><button class="button button-outline" id="syncInstagram">↻ Sincronizar Instagram</button><button class="button button-outline" id="downloadMetrics">↓ Descargar CSV</button></div><p id="igMessage" class="form-message"></p><div class="metric-cards"><div class="metric-summary"><span>VISTAS</span><b>${sum('views').toLocaleString('es-CL')}</b></div><div class="metric-summary"><span>ALCANCE ÚNICO</span><b>${sum('reach').toLocaleString('es-CL')}</b></div><div class="metric-summary"><span>SEGUIDORES / ALCANCE</span><b>${fmt(mean('follow'))}</b></div><div class="metric-summary"><span>VISITAS PERFIL / ALCANCE</span><b>${fmt(mean('profile'))}</b></div><div class="metric-summary"><span>COMENTARIOS + COMPARTIDOS / ALCANCE</span><b>${fmt(mean('comment')+mean('share'))}</b></div><div class="metric-summary"><span>GUARDADOS / ALCANCE</span><b>${fmt(mean('save'))}</b></div><div class="metric-summary"><span>RETENCIÓN MEDIA / DURACIÓN</span><b>${fmt(mean('watch'))}</b></div><div class="metric-summary"><span>CONSULTAS REGISTRADAS</span><b>${sum('inquiries')}</b></div></div><p class="muted-intro">Tu mejor pieza por conversión a seguidores en este periodo: <b>${top?esc(top.title)+' · '+esc(top.platform||'Instagram')+' · '+fmt(rates(top).follow):'aún faltan datos'}</b>. La conversión a consultas se lee junto con tu objetivo; no todos los videos deben vender.</p><h3 style="font-size:12px;margin:24px 0 9px">Embudo por red y pilar</h3><div class="table-wrap"><table class="metric-table"><thead><tr><th>RED</th><th>PILAR</th><th>PIEZAS</th><th>ALCANCE</th><th>SEGUIDORES</th><th>SEGUIDORES / ALC.</th><th>COMENT. + COMP. / ALC.</th></tr></thead><tbody>${groups.map(g=>`<tr><td>${esc(g.platform)}</td><td>${esc(pillarName(g.p))}</td><td>${g.count}</td><td>${g.reach.toLocaleString('es-CL')}</td><td>${g.followers}</td><td>${fmt(g.followRate)}</td><td>${fmt(g.connectionRate)}</td></tr>`).join('')||'<tr><td colspan="7">Cuando registres resultados, aparecerá aquí qué pilares generan conexión y crecimiento.</td></tr>'}</tbody></table></div><div id="metricMessage" class="form-message"></div><h3 style="font-size:12px;margin:24px 0 9px">Registrar resultados de un video</h3><form id="metricForm" class="metric-form"><input name="title" required placeholder="Tema o nombre del video"><input name="date" type="date" required value="${localDate()}" aria-label="Fecha de publicación"><select name="platform"><option value="instagram">Instagram</option><option value="tiktok">TikTok</option></select><select name="pillar"><option value="business">Emprendimiento y negocios</option><option value="ai">IA aplicada</option><option value="automation">Automatización y sistemas</option><option value="personal">Desarrollo personal</option></select><select name="objective"><option value="connection">Conexión</option><option value="discovery">Descubrimiento</option><option value="authority">Aprendizaje / autoridad</option><option value="conversion">Consulta por producto/servicio</option></select><input name="duration" type="number" min="1" placeholder="Duración (s)"><input name="views" type="number" min="0" placeholder="Vistas"><input name="reach" type="number" min="0" placeholder="Alcance"><input name="avgWatch" type="number" min="0" step="0.1" placeholder="Watch medio (s)"><input name="likes" type="number" min="0" placeholder="Me gusta"><input name="comments" type="number" min="0" placeholder="Comentarios"><input name="saves" type="number" min="0" placeholder="Guardados"><input name="shares" type="number" min="0" placeholder="Compartidos"><input name="profileVisits" type="number" min="0" placeholder="Visitas al perfil"><input name="followersGained" type="number" min="0" placeholder="Seguidores atribuidos"><input name="inquiries" type="number" min="0" placeholder="DM / consultas"><button class="button button-lime" type="submit">Guardar resultados <span>＋</span></button></form><h3 style="font-size:12px;margin:24px 0 9px">Videos medidos · ${ms.length} en este periodo</h3><div class="table-wrap"><table class="metric-table"><thead><tr><th>VIDEO</th><th>RED</th><th>PILAR</th><th>ALCANCE</th><th>SEGUIDORES</th><th>PERFIL</th><th>CONSULTAS</th><th>COMENTARIOS</th><th></th></tr></thead><tbody>${ms.slice().sort((a,b)=>(b.date||'').localeCompare(a.date||'')).map(m=>`<tr><td>${esc(m.title)}</td><td>${esc(m.platform||'instagram')}</td><td>${esc(pillarName(m.pillar))}</td><td>${Number(m.reach||0).toLocaleString('es-CL')}</td><td>${Number(m.followersGained||0)} · ${fmt(rates(m).follow)}</td><td>${Number(m.profileVisits||0)}</td><td>${Number(m.inquiries||0)}</td><td>${Number(m.comments||0)}</td><td><button class="text-button remove-metric" data-id="${esc(m.id)}">×</button></td></tr>`).join('')||'<tr><td colspan="9">Aún no hay mediciones en este periodo. Usa los Insights de Instagram o captura los datos manualmente.</td></tr>'}</tbody></table></div><p class="muted-intro" style="margin-top:12px">${all.length} mediciones guardadas. Para comparar un video, registra su rendimiento siempre en un momento parecido (por ejemplo, a los 15 días).</p></section>`}
function wireView(){
  $('#quickCapture')?.addEventListener('submit',e=>{e.preventDefault();const title=$('#captureTitle').value.trim(),facts=$('#captureNote').value.trim(),pillar=$('#capturePillar').value;userData.customIdeas.unshift({id:`C${Date.now().toString().slice(-6)}`,title,pillar,source:'CAPTURA',facts,action:'',outcome:'',learning:'',review:'Completar hechos antes de publicar.',status:'needs_details',sensitive:false});save();renderView();notify('Historia guardada.')});
  $('#ideaPillarFilter')?.addEventListener('change',filterIdeas);$('#ideaStatusFilter')?.addEventListener('change',filterIdeas);
  $$('.save-note').forEach(b=>b.onclick=()=>{const id=b.dataset.id,n=$(`.story-notes[data-id="${id}"]`).value.trim();const s=allStories().find(x=>x.id===id);if(s)s.userNotes=n;save();notify('Contexto guardado en este navegador.')});
  $('#generatePrompt')?.addEventListener('click',()=>{buildGenerationPrompt();notify('Pedido listo para pegar en el chat.')});$('#generationCount')?.addEventListener('input',buildGenerationPrompt);$('#generationPillar')?.addEventListener('change',buildGenerationPrompt);$('#copyGenerationPrompt')?.addEventListener('click',async()=>{if(!$('#generationPrompt').value)buildGenerationPrompt();try{await navigator.clipboard.writeText($('#generationPrompt').value);notify('Pedido copiado. Pégalo en el chat del asistente.')}catch{notify('Selecciona y copia el pedido manualmente.')}});$$('.use-inspiration').forEach(b=>b.onclick=()=>{promptSeed=b.dataset.hook||'';setView('inspiration');$('#generationPillar').value=b.dataset.pillar;buildGenerationPrompt();$('#generationPrompt').focus()});$$('.copy-story-template').forEach(b=>b.onclick=async()=>{const t=storyTemplates.find(x=>x.id===b.dataset.id);if(!t)return;try{await navigator.clipboard.writeText(`${t.title}\n${t.frames.join('\n')}`);notify('Formato copiado.')}catch{notify('No se pudo copiar el formato.')}});$('#newStory')?.addEventListener('click',()=>{const title=prompt('¿Qué pasó? Escribe un título breve.');if(!title)return;const facts=prompt('Anota el hecho con tus palabras. No agregues cifras que no recuerdes.','');if(facts===null)return;userData.customIdeas.unshift({id:`C${Date.now().toString().slice(-6)}`,title,pillar:$('#capturePillar')?.value||'business',source:'CAPTURA',facts,action:'',outcome:'',learning:'',review:'Completar contexto y confirmar antes de guionizar.',status:'needs_details',sensitive:false});save();setView('stories');notify('Historia capturada.')});
  $('#newScript')?.addEventListener('click',()=>{const title=prompt('Título breve del contenido');if(!title)return;const pillar=$('#capturePillar')?.value||'business';userData.scripts.unshift({id:`S${Date.now()}`,title,pillar,series:'',objective:'connection',format:'hablar-a-camara',duration:'30–45s',hook:'',body:'',payoff:'',cta:'',status:'draft',review:true});save();renderView()});
  $('#saveBatch')?.addEventListener('click',()=>{userData.firstBatch.forEach(v=>{const ta=$(`.batch-script[data-batch="${v.id}"]`),st=$(`[data-batch-status="${v.id}"]`),dt=$(`[data-batch-date="${v.id}"]`),rv=$(`[data-batch-review="${v.id}"]`);v.script=ta?.value||'';v.status=st?.value||v.status;v.publishedAt=dt?.value||null;v.reviewed=!!rv?.checked});save();renderView();notify('Primera tanda guardada.')});
  $$('.use-hook').forEach(b=>b.onclick=()=>{const s=userData.scripts.find(x=>x.id===b.dataset.id);if(s){s.hook=(s.hookOptions||[])[Number(b.dataset.hook)]||s.hook;save();renderView()}});
  $$('.script-card textarea[data-script-field]').forEach(el=>el.addEventListener('change',()=>{const s=userData.scripts.find(x=>x.id===el.dataset.id);if(s)s[el.dataset.scriptField]=el.value;save()}));
  $$('[data-script-status]').forEach(el=>el.onchange=()=>{const s=userData.scripts.find(x=>x.id===el.dataset.scriptStatus);if(s){s.status=el.value;save();notify('Estado actualizado.')}});
  $$('.delete-script').forEach(b=>b.onclick=()=>{userData.scripts=userData.scripts.filter(x=>x.id!==b.dataset.id);save();renderView();notify('Borrador quitado.')});
  $('#metricForm')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget);const m=Object.fromEntries(f.entries());m.id=`M${Date.now()}`;for(const k of ['duration','views','reach','likes','comments','saves','shares','avgWatch','profileVisits','followersGained','inquiries'])m[k]=Number(m[k]||0);userData.metrics.push(m);save();renderView();notify('Métrica guardada.')});
  $$('.remove-metric').forEach(b=>b.onclick=()=>{userData.metrics=userData.metrics.filter(x=>x.id!==b.dataset.id);save();renderView()});
  $('#metricWindow')?.addEventListener('change',()=>renderView());$('#connectIg')?.addEventListener('click',connectIg);$('#syncInstagram')?.addEventListener('click',syncInstagram);$('#downloadMetrics')?.addEventListener('click',downloadCsv);
  $('#exportProduction')?.addEventListener('click',exportProduction);$('#importProduction')?.addEventListener('click',()=>$('#productionFile').click());$('#productionFile')?.addEventListener('change',importProduction);$('#loadPackage')?.addEventListener('click',loadPackage);

}
function filterIdeas(){const p=$('#ideaPillarFilter')?.value||'all',s=$('#ideaStatusFilter')?.value||'all';$$('.story-card').forEach(el=>el.classList.toggle('hidden',(p!=='all'&&el.dataset.pillar!==p)||(s!=='all'&&el.dataset.status!==s)))}
function exportJson(obj,name){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}));a.download=name;a.click();URL.revokeObjectURL(a.href)}
function exportProduction(){exportJson({schemaVersion:2,activeSaasStage:userData.activeSaasStage||1,stories:userData.stories,customIdeas:userData.customIdeas,scripts:userData.scripts,firstBatch:userData.firstBatch},'benja-produccion-contenido.json')}
function importProduction(e){const file=e.target.files?.[0];if(!file)return;const r=new FileReader();r.onload=()=>{try{const obj=JSON.parse(r.result);if(Array.isArray(obj.scripts))userData.scripts=[...obj.scripts,...userData.scripts];if(Array.isArray(obj.stories))userData.customIdeas=[...obj.stories,...(userData.customIdeas||[])];save();renderView();notify('Piezas importadas.')}catch{notify('Ese archivo no contiene piezas JSON válidas.')}};r.readAsText(file);e.target.value=''}
function loadPackage(){const box=$('#packageJson');try{const pack=JSON.parse(box.value);if(!Array.isArray(pack.scripts)||!pack.scripts.length)throw Error('Agrega al menos una pieza dentro de scripts.');if(pack.scripts.some(x=>x.series==='saas_build'&&Number(x.stage||1)>Number(userData.activeSaasStage||1)))throw Error('Esa pieza pertenece a una etapa posterior de la serie SaaS. Mantén cerrada esa etapa hasta revisar la actual.');const ids=new Set(userData.scripts.map(x=>x.id));const next=pack.scripts.map((x,i)=>{const id=String(x.id||`S${Date.now()}-${i}`);if(ids.has(id))throw Error(`El ID ${id} ya existe.`);ids.add(id);return {id,title:String(x.title||'Contenido sin título'),pillar:['business','personal','ai','automation','founder'].includes(x.pillar)?x.pillar:'business',stage:Number(x.stage||1),series:String(x.series||''),objective:String(x.objective||'connection'),format:String(x.format||'hablar-a-camara'),duration:String(x.duration||'30–45s'),hook:String(x.hook||''),body:String(x.body||''),payoff:String(x.payoff||''),cta:String(x.cta||''),status:['draft','ready','production'].includes(x.status)?x.status:'ready',review:String(x.review||''),sourceStoryId:String(x.sourceStoryId||''),hookOptions:Array.isArray(x.hookOptions)?x.hookOptions.map(String).slice(0,5):[]}});userData.scripts=[...next,...userData.scripts];save();renderView();notify(`${next.length} piezas cargadas a producción en este navegador.`)}catch(e){notify(e.message||'JSON inválido. No se cargó nada.')}}

function downloadCsv(){const rows=[['titulo','fecha','plataforma','pilar','objetivo','duracion_s','vistas','alcance','seguidores_atribuidos','visitas_perfil','consultas','me_gusta','comentarios','guardados','compartidos','watch_promedio_s','interacciones_por_alcance_pct','seguidores_por_alcance_pct'],...getMetrics().map(m=>{const q=rates(m);return [m.title,m.date,m.platform,m.pillar,m.objective,m.duration,m.views,m.reach,m.followersGained,m.profileVisits,m.inquiries,m.likes,m.comments,m.saves,m.shares,m.avgWatch,q.engagement.toFixed(2),q.follow.toFixed(2)]})];const csv=rows.map(row=>row.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));a.download='metricas-reels-benja.csv';a.click();URL.revokeObjectURL(a.href)}
function importBackup(){const input=$('#importFile');input.click();input.onchange=()=>{const file=input.files?.[0];if(!file)return;const r=new FileReader();r.onload=()=>{try{const d=JSON.parse(r.result);if(!d||!Array.isArray(d.stories)||!Array.isArray(d.firstBatch))throw Error();userData=d;save();notify('Respaldo importado.')}catch{notify('El archivo no parece un respaldo válido.')}};r.readAsText(file)}}
function exportBackup(){exportJson(userData,'respaldo-estudio-benja.json')}
async function checkIgConfig(){try{const r=await fetch('/api/instagram-status');if(!r.ok)return;const d=await r.json(),status=$('#igStatus'),button=$('#connectIg'),message=$('#igMessage');if(status)status.textContent=d.connected?'CONECTADO':d.ready?'LISTO PARA AUTORIZAR':'PENDIENTE CONFIGURACIÓN';if(button)button.textContent=d.ready?(d.connected?'Actualizar Instagram ↗':'Autorizar con Instagram ↗'):'Conectar Instagram ↗';if(message)message.textContent=d.connected?`Cuenta conectada: @${d.username||'Instagram'}.`:'La sincronización automática de Instagram requiere configurar la app gratuita de Meta.'}catch{}}
async function syncInstagram(){const el=$('#metricMessage');el.textContent='Consultando métricas de Instagram…';try{const r=await fetch('/api/instagram-metrics');const d=await r.json();if(!r.ok)throw Error(d.error||'No se pudo conectar.');for(const x of d.media||[]){if(!x.insights)continue;const exists=userData.metrics.find(m=>m.instagramId===x.id);const val=k=>x.insights[k]??0;const metrics={id:exists?.id||`IG${x.id}`,instagramId:x.id,title:(x.caption||'Reel sin título').slice(0,90),date:(x.timestamp||'').slice(0,10),platform:'instagram',pillar:exists?.pillar||'unclassified',objective:exists?.objective||'connection',duration:Number(x.video_duration||exists?.duration||0),views:Number(val('views')),reach:Number(val('reach')),likes:Number(x.like_count||val('likes')),comments:Number(x.comments_count||val('comments')),saves:Number(val('saved')),shares:Number(val('shares')),followersGained:Number(val('follows')),profileVisits:Number(val('profile_visits')),inquiries:exists?.inquiries||0,avgWatch:Number(val('ig_reels_avg_watch_time'))/1000,source:'instagram-api'};if(exists)Object.assign(exists,metrics);else userData.metrics.push(metrics)}save();renderView();$('#metricMessage').textContent=`Importados/actualizados ${d.media?.filter(x=>x.insights).length||0} Reels con métricas disponibles.`}catch(err){el.textContent=err.message}}
async function connectIg(){const msg=$('#igMessage');try{const r=await fetch('/api/instagram-status'),d=await r.json();if(!d.ready){if(msg)msg.textContent='Falta crear la app gratuita en Meta y configurar sus credenciales privadas en Vercel; guía en README.';return}location.href='/api/instagram-auth'}catch{if(msg)msg.textContent='No se pudo revisar la configuración de Instagram.'}}
function setupEvents(){
  $('#lockForm').addEventListener('submit',async e=>{e.preventDefault();const msg=$('#lockMessage'),v=$('#localPin').value;if(v.length<6){msg.textContent='Usa una clave de al menos 6 caracteres.';return}const saltText=localStorage.getItem(KEYS.salt);if(!saltText){const salt=crypto.getRandomValues(new Uint8Array(16));dataKey=await deriveKey(v,salt);localStorage.setItem(KEYS.salt,b64(salt));localStorage.setItem(KEYS.hash,await sha(v,salt));initLocal();await save();showApp();notify('Clave local creada.')}else{const salt=Uint8Array.from(atob(saltText),c=>c.charCodeAt(0)),hash=await sha(v,salt);if(hash===localStorage.getItem(KEYS.hash)){try{dataKey=await deriveKey(v,salt);initLocal(await loadLocal(dataKey));showApp()}catch{msg.textContent='No pude descifrar tus datos. Revisa la clave o restaura un respaldo.'}}else msg.textContent='La clave no coincide.'}});
  $$('.side-link').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));$$('[data-goto]').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.goto)));

  $('#exportData').onclick=exportBackup;$('#importData').onclick=importBackup;$('#lockNow').onclick=()=>location.reload();$('#settingsButton').onclick=()=>notify('Respaldo local en el menú izquierdo. Datos cifrados y no sincronizados a la nube.');
}
async function start(){try{initLocal();setupEvents();await enterStudio()}catch(e){$('#lockMessage').textContent='No pude iniciar el Estudio en este navegador.'}}
start();
